/**
 * A unique violation reaches a caller as a 409 `AsasError` whose message names no
 * column, so the constraint is identified by the cause chain the refusal keeps.
 */
const refusal = (results: readonly PromiseSettledResult<unknown>[]) => {
  const rejected = results.find((result) => result.status === 'rejected') as PromiseRejectedResult | undefined
  assert.ok(rejected?.reason instanceof AsasError, 'the write that lost the race is a refusal the caller can act on')
  assert.equal(rejected.reason.status, 409, 'and it carries the status a collision gets')
  assert.equal(rejected.reason.key, 'error.conflict.unique', 'with the key a client resolves')
  let deepest: unknown = rejected.reason
  while ((deepest as { cause?: unknown } | undefined)?.cause) deepest = (deepest as { cause?: unknown }).cause
  return String(deepest)
}

const columnsOf = async (table: string) => {
  const { rows } = await db.execute(
    `select column_name from information_schema.columns where table_schema = 'public' and table_name = '${table}' order by ordinal_position`,
  )
  return rows.map((row) => row.column_name)
}

const offlineTargets = (
  kinds: Record<string, ColumnBuilder> = drizzleKinds,
  shapes: Record<string, ZodShape> = zodKinds,
  rules: Record<string, ColumnRule> = drizzleRules,
) => ({
  drizzle: drizzleAdapter({ connectionString: 'postgresql://never-connected', kinds, rules }),
  zod: { ...zodTarget, kinds: shapes, rules: zodRules },
  service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'drizzle', schema: 'zod', authorize: defaultAuthorize }),
})

const reporting = <L extends { buildAsas: (args: never) => unknown }>(language: L): L => ({
  ...language,
  buildAsas: ((args: { auth?: object }) => language.buildAsas({ ...args, auth: { onError: console.error, ...args.auth } } as never)) as L['buildAsas'],
})

const offline = (kinds?: Record<string, ColumnBuilder>, shapes?: Record<string, ZodShape>, rules?: Record<string, ColumnRule>) =>
  reporting(defineMithaq({ arkan: [base], targets: offlineTargets(kinds, shapes, rules) }))

/** A screen lists every kayan it draws and refuses a build missing one. */
const screen = (kayan: readonly string[], controls: Record<string, ScreenKind> = screenKinds) =>
  screenTarget({
    ...dashboardScreen,
    kayan,
    controls,
    // The dashboard alone, and without its key: the members page names
    // `memberRoles.find` and the dashboard `courses.find`, keys only a build
    // holding those kayan can answer.
    pages: { dashboard: { path: '/', component: dashboardScreen.pages.dashboard!.component } },
    components: { ...dashboardScreen.components, money: dashboardScreen.components.activity },
  })

const screened = (...kayan: string[]) => {
  const { service, ...stores } = offlineTargets()
  return reporting(defineMithaq({ arkan: [base], targets: { ...stores, dashboard: screen(kayan), service } }))
}

/**
 * Each build holds some of the kayan the project's roles name, so it runs over the roles
 * narrowed to what it holds.
 */
const onScreen = (...kayan: string[]) =>
  narrowed((roles) => defineMithaq({
    locales: ['ar', 'en'] as const,
    arkan: [base],
    targets: {
      ...projectTargets,
      rbac: accessTarget(roles as typeof systemRoles),
      dashboard: screen([...kayan, 'roles', 'memberRoles', 'user', 'organization']),
      platform: { ...platformScreen, kayan: ['roles', 'memberRoles', 'user', 'organization', 'member'] },
      portal: { ...portalScreen, kayan: ['user'] },
    },
  }))

const online = () =>
  reporting(defineMithaq({
    arkan: [base],
    targets: {
      drizzle: drizzleAdapter({ db, kinds: drizzleKinds, rules: drizzleRules }),
      zod: { ...zodTarget, kinds: zodKinds, rules: zodRules },
      service: serviceTarget({
        depth: defaultDepth,
        defaultLimit,
        maxLimit: defaultMaxLimit,
        joinLimit: defaultJoinLimit,
        bulkLimit: defaultBulkLimit,
        store: 'drizzle',
        schema: 'zod',
        authorize: defaultAuthorize,
        afterSteps: [],
      }),
    },
  }))

const sqlTypes = (table: unknown) => table as Record<string, { getSQLType(): string }>

/**
 * The organization column of the template's `courses`, as a plain one, for a test whose own shared
 * kayan writes through that table: the column is NOT NULL and names an organization, so it is
 * filled with one `before` makes. The runner's scope over a tenant-owned kayan is
 * `tenant-scope.test.ts`'s; these tests are about the table they borrow.
 */
const borrowed = { organization: { kind: 'text', rules: { defaultValue: 'borrowed-organization' } } } as const

const localAuthFields = { ...defaultFields, ...shippedLocalAuthFields }
const localOperations = { ...defaultOperations, ...localAuthOperations }

const localRequired = {
  tokenExpiration: defaultTokenExpiration,
  maxLoginAttempts: defaultMaxLoginAttempts,
  lockTime: defaultLockTime,
  ip: () => null,
  email: { send: async () => {} },
}

/**
 * The provider reads the account's row on every path it has, and each is a sign-in for
 * the account it finds.
 */
const softLocalUsers = defineTestKayan({
  name: 'softLocalUsers',
  dbName: 'soft_local_users',
  access: allowAccess,
  fields: {
    ...defaultFields,
    ...localAuthFields,
    deletedAt: {
      kind: 'datetime',
      label: { en: 'Deleted at', ar: 'تاريخ الحذف' },
      rules: { providedBy: { create: 'never', update: 'never' } },
    },
  },
  targets: { service: { operations: localOperations } },
})
const softLocalAsas = buildTestAsas({
  http: [fetchHttp()],
  kayan: [authenticating(softLocalUsers, local({ ...localRequired, secret: 'soft-local-users-secret-of-thirty-two-characters' })), ...accessKayan],
})

/**
 * Each project starts empty, so `first-register` is open in it and a lockout on one
 * account cannot reach another test's rows.
 */
const localAuthProject = async (
  name: string,
  provider: {
    email?: { send: (message: { to: string; kind: 'verification' | 'reset'; token: string; user: Record<string, unknown> }) => Promise<void> }
    ip?: (request: Request) => string | null | undefined
    lockTime?: number
    maxLoginAttempts?: number
    tokenExpiration?: number
    development?: boolean
    secret?: string
    onError?: (error: unknown) => void
  } = {},
  extraFields: Record<string, unknown> = {},
  admin?: { access: (args: AdminAccessArgs<{ user: { email: string } }>) => boolean },
  access: Record<'create' | 'read' | 'update' | 'delete', () => boolean> = {
    create: () => true,
    read: () => false,
    update: () => false,
    delete: () => false,
  },
) => {
  const language = online()
  const kayan = language.defineKayan({
    name,
    dbName: name.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`),
    access,
    fields: { ...defaultFields, ...localAuthFields, ...extraFields } as typeof localAuthFields,
    targets: { service: { operations: localOperations } },
  })
  const { onError = console.error, ...options } = provider
  const authenticated = authenticating(kayan, local({ ...localRequired, secret: `${name}-a-local-auth-test-secret`, ...options }))
  const built = language.buildAsas({
    http: [fetchHttp()],
    kayan: [authenticated],
    auth: { onError, ...(admin && { admin: { kayan: authenticated, access: admin.access } }) },
  })
  await built.connect()
  return { built, kayan }
}

const call = (
  built: { handler(request: Request): Promise<Response> },
  path: string,
  init: RequestInit = {},
) => built.handler(new Request(`http://test/api/auth/local/${path}`, init))

const served = (
  built: { handler(request: Request): Promise<Response> },
  path: string,
  body: unknown,
  headers: Record<string, string> = {},
) =>
  built.handler(
    new Request(`http://test/api/${path}`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: JSON.stringify(body) }),
  )
const notFound = (thrown: unknown) => thrown instanceof AsasError && thrown.status === 404 && thrown.key === 'error.not_found.row'
const login = (built: { handler(request: Request): Promise<Response> }, email: string, password: string) =>
  call(built, 'login', { method: 'POST', body: JSON.stringify({ email, password }) })

const firstAccount = async (
  built: { handler(request: Request): Promise<Response> },
  email: string,
  password = 'a-long-enough-password',
) => {
  const response = await call(built, 'first-register', { method: 'POST', body: JSON.stringify({ email, password }) })
  assert.equal(response.status, 201)
  return { response, cookie: response.headers.get('set-cookie') ?? '' }
}

