test('24b. a build whose kayan carry auth names its own auth.onError, which hears a strategy that failed and an access target that could not answer', async () => {
  const language = defineMithaq({ arkan: [base], targets: offlineTargets() })
  const users = language.defineKayan({ name: 'users', fields: localAuthFields, targets: { service: { operations: localOperations } } })
  assert.throws(
    () => language.buildAsas({ http: [fetchHttp()], kayan: [authenticating(users, local({ ...localRequired, development: true }))] }),
    /buildAsas was handed no "auth\.onError", and kayan "users" carries auth\./,
  )

  // A strategy that throws is the next one's turn and no actor, and the project's own
  // function is told, never the console.
  const fault = new Error('The strategy threw.')
  const failing = language.defineKayan({
    name: 'failing',
    fields: { id: defaultFields.id },
    auth: { name: 'failing', authenticate: () => { throw fault } },
    targets: { service: { operations: defaultOperations } },
  })
  const heard: unknown[] = []
  const built = language.buildAsas({ http: [fetchHttp()], kayan: [failing], auth: { onError: (error) => void heard.push(error) } })
  assert.equal(await built.auth.actor(new Headers()), null)
  assert.equal(heard.length, 1, 'told once')
  assert.match((heard[0] as Error).message, /Auth strategy "failing" failed\./)
  assert.equal((heard[0] as Error).cause, fault, 'carrying what the strategy threw')

  const down = new Error('The role store is down.')
  heard.length = 0
  const strategy = betterAuthStrategy({
    server: { api: { getSession: async () => ({ user: { id: 'one' }, session: { activeOrganizationId: 'org' } }) }, handler: async () => new Response() } as never,
    collection: 'user',
    assigned: () => { throw down },
    onError: (error) => void heard.push(error),
  })
  const { user } = await strategy.authenticate({ headers: new Headers() })
  assert.deepEqual(actorPermissions(user), new Set(), 'the actor holds no key')
  assert.equal(heard.length, 1, 'told once')
  assert.match((heard[0] as Error).message, /The access target failed to resolve, so this actor holds no role and no key\./)
  assert.equal((heard[0] as Error).cause, down)

  const broken = new Error('The session store is down.')
  heard.length = 0
  const routed = betterAuthStrategy({
    server: { api: { getSession: async () => { throw broken } }, handler: async () => new Response('served') } as never,
    collection: 'user',
    onError: (error) => void heard.push(error),
  })
  assert.equal(await (await routed.handler(new Request('http://test/api/auth/user/get-session'))).text(), 'served', 'the provider still answers its own route')
  assert.equal(heard.length, 1, 'told once')
  assert.match((heard[0] as Error).message, /Resolving the actor of a Better Auth request failed, so it holds no key\./)
  assert.equal((heard[0] as Error).cause, broken)
})

