test('141. in a build graded by the template\'s own access target, a local-auth role column holds no key, a second Better Auth instance is refused beside a tenant-owned kayan, and the admin kayan\'s session holds the platform\'s', async () => {
  const localWithRole = defineTestKayan({
    name: 'platformLocalUsers',
    dbName: 'platform_local_users',
    access: allowAccess,
    fields: { ...localAuthFields, role: { kind: 'text' } },
    targets: { service: { operations: localOperations } },
  })
  // A second instance whose session answers `super_admin` in `user.role` for
  // whoever asks: the column is set, the provider is Better Auth, and the kayan
  // is not the one `auth.admin` names.
  const customers = defineTestKayan({
    name: 'platformCustomers',
    dbName: 'platform_customers',
    access: allowAccess,
    fields: { id: { kind: 'text' }, role: { kind: 'text' } },
    auth: betterAuthProvider({
      server: () => ({
        api: { getSession: async () => ({ user: { id: 'customer-1', role: 'super_admin' } }) },
        handler: async () => new Response('ok'),
      }),
    }),
    targets: { service: { operations: defaultOperations } },
  })
  // Its organizations are not the ones the tenant field points at, so a build holding a
  // tenant-owned kayan, as the role kayan are, refuses it before its column could answer.
  assert.throws(
    () => buildTestAsas({ http: [fetchHttp()], kayan: [...accessKayan, customers] }),
    /Kayan "user" and "platformCustomers" each carry Better Auth, and kayan "roles" belongs to the organization a session names/,
  )
  const built = buildTestAsas({
    http: [fetchHttp()],
    kayan: [...accessKayan, authenticating(localWithRole, local({ ...localRequired, secret: 'platform-local-secret-of-thirty-two-characters' }))],
  })
  // The adapter is the one `asas` itself holds, so its pool is closed by the
  // file's own `after` and never here.
  await built.connect()
  const strategy = (name: string) => built.auth.strategies.find((one) => one.name === name)!
  const { cookie } = await firstAccount(built, 'platform-local@example.com')
  await db.execute(`update "platform_local_users" set role = 'super_admin' where email = 'platform-local@example.com'`)
  const carrier = (await asPlatform(() => strategy('local').authenticate({ headers: new Headers({ cookie: cookie.split(';')[0]! }) }))).user
  assert.equal((carrier as { role?: string }).role, 'super_admin', 'the local column reaches the actor')
  assert.deepEqual([...(actorPermissions(carrier) as ReadonlySet<string>)], [], 'and it holds no key')

  // The same build grades the admin kayan's session, so the empty set above is
  // the guard and not a build that grades nothing.
  const platform = await server.api.signUpEmail({
    body: { name: 'Graded', email: 'platform-graded@example.com', password: 'a-long-enough-password' },
    returnHeaders: true,
  })
  await db.execute(`update "user" set role = 'super_admin' where id = '${platform.response.user.id}'`)
  const admin = (await asPlatform(async () => strategy('user').authenticate({ headers: (await onPlatform(new Headers({ cookie: platform.headers.get('set-cookie') ?? '' }))) }))).user
  assert.equal(actorPermissions(admin), true, 'the admin kayan\'s session holds the platform\'s keys in the platform app')
})

test('143. the runner is a target: a build with none is refused naming the fix, a second is refused, one under another name is refused by that name, transport inside it is refused, and any of its ten keys left on the language root is refused by name', () => {
  const targets = () => ({
    drizzle: drizzleAdapter({ connectionString: 'postgresql://never-connected', kinds: drizzleKinds, rules: drizzleRules }),
    zod: zodTarget,
  })
  const runner = () => serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, authorize: defaultAuthorize, store: 'drizzle', schema: 'zod' })
  // Written as data, the way a loader hands a language over. A root key and a transport
  // inside the runner are type errors where they are written, and none, two and a misnamed
  // runner are refused here alone.
  const build = (language: Record<string, unknown>) => () =>
    (defineMithaq({ arkan: [base], ...language } as never) as unknown as {
      buildAsas: (args: { kayan: Kayan[]; http: unknown[] }) => unknown
    }).buildAsas({ http: [fetchHttp()], kayan: [{ name: 'notes', fields: { id: defaultFields.id, title: { kind: 'text' } } }] })

  assert.doesNotThrow(build({ targets: { ...targets(), service: runner() } }))

  assert.throws(
    build({ targets: targets() }),
    /This build declares no target of capability "service", and a build with no runner publishes nothing\. Add service: serviceTarget\(\{ authorize, depth, defaultLimit, maxLimit, joinLimit, bulkLimit, store, schema \}\) to targets\./,
  )
  // Exactly one, for the reason exactly one admin is: two runners are two
  // answers to what an operation does.
  assert.throws(
    build({ targets: { ...targets(), service: runner(), second: runner() } }),
    /Targets "service" and "second" both declare capability "service", and a build has exactly one service target\./,
  )
  assert.throws(
    build({ targets: { ...targets(), runner: runner() } }),
    /Target "runner" declares capability "service" and has to be named "service" in targets/,
  )
  for (const transport of ['http', 'orpc']) {
    assert.throws(
      build({ targets: { ...targets(), service: { ...runner(), [transport]: [fetchHttp()] } } }),
      new RegExp(`The service target declares "${transport}", and transport is not the runner's`),
    )
  }
  // The nine keys the runner took from the root are refused there by name, whichever one it
  // is, rather than read as a build missing its runner or kept as a second
  // spelling of one fact.
  const nine = {
    beforeSteps: [],
    afterSteps: [audit],
    afterCommit: [],
    authorize: defaultAuthorize,
    softDelete: 'deletedAt',
    store: 'drizzle',
    schema: 'zod',
    audit: () => {},
    depth: 4,
  }
  for (const [key, value] of Object.entries(nine)) {
    assert.throws(
      build({ targets: { ...targets(), service: runner() }, [key]: value }),
      new RegExp(`"${key}" is not a key of the language: it is a key of the service target\\. Move it into targets\\.service`),
    )
  }
  assert.throws(
    build({ targets: { ...targets(), service: runner() }, operations: defaultOperations }),
    /The language declares "operations", and a kayan's operations are its own: write them under targets: \{ service: \{ operations: \{ \.\.\.defaultOperations \} \} \} on each kayan\./,
  )
})

test('144. audit and depth on the language root are refused by name', () => {
  const runner = serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, authorize: defaultAuthorize, store: 'drizzle', schema: 'zod' })
  for (const [key, value] of Object.entries({ audit: () => {}, depth: 4 })) {
    assert.throws(
      () => (defineMithaq as any)({ arkan: [base], targets: {
        drizzle: drizzleAdapter({ connectionString: 'postgresql://never-connected', kinds: drizzleKinds, rules: drizzleRules }),
        zod: zodTarget,
        service: runner,
      }, [key]: value }).buildAsas({ http: [fetchHttp()], kayan: [] }),
      new RegExp(`"${key}" is not a key of the language: it is a key of the service target`),
    )
  }
})

test('145. a listed audit step requires a service sink', () => {
  const targets = {
    drizzle: drizzleAdapter({ connectionString: 'postgresql://never-connected', kinds: drizzleKinds, rules: drizzleRules }),
    zod: zodTarget,
  }
  const build = (afterSteps: readonly Step[], auditSink?: AuditHandler) =>
    defineMithaq({ arkan: [base], targets: {
      ...targets,
      service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, authorize: defaultAuthorize, store: 'drizzle', schema: 'zod', afterSteps, ...(auditSink ? { audit: auditSink } : {}) }),
    } }).buildAsas({ http: [fetchHttp()], kayan: [] })
  assert.throws(() => build([audit]), /The service target lists the "audit" step without an audit sink.*Declare.*audit.*drop the step/)
  assert.doesNotThrow(() => build([audit], () => {}))
  assert.doesNotThrow(() => build([]))
  assert.doesNotThrow(() => build([], () => {}))
  const language = defineMithaq({ arkan: [base], targets: {
    ...targets,
    service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, authorize: defaultAuthorize, store: 'drizzle', schema: 'zod' }),
  } })
  assert.throws(() => language.buildAsas({ http: [fetchHttp()], kayan: [language.defineKayan({
    name: 'notes', fields: { id: defaultFields.id }, targets: { service: { operations: { ...defaultOperations, create: { steps: [insert], afterSteps: [audit] } } } },
  })] }), /Kayan "notes" operation "create" lists the "audit" step without an audit sink\. Declare audit on the service target or drop the step\./)
  // A project's own record, spread by every kayan that wants it, is checked on each kayan
  // that spreads it.
  const audited = { ...defaultOperations, create: { steps: [insert], afterSteps: [audit] } }
  assert.throws(() => language.buildAsas({ http: [fetchHttp()], kayan: [language.defineKayan({
    name: 'shared', fields: { id: defaultFields.id }, targets: { service: { operations: audited } },
  })] }), /Kayan "shared" operation "create" lists the "audit" step without an audit sink/)
})

test('146. a built kayan is name, fields, operations and targets, and the two operation paths are one object', async () => {
  const memory = memoryStore()
  const language = defineMithaq({
    arkan: [base],
    targets: {
      memory,
      zod: zodTarget,
      service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'memory', schema: 'zod', authorize: defaultAuthorize }),
    },
  })
  const notes = language.defineKayan({
    name: 'placedNotes',
    access: allowAccess,
    fields: { id: { kind: 'text' }, title: { kind: 'text', rules: { required: true } } },
    targets: {
      service: {
        operations: {
          ...defaultOperations,
          shout: {
            steps: ({ steps }) => [steps.update],
          },
        },
      },
    },
  })
  const built = language.buildAsas({ http: [fetchHttp()], kayan: [notes] })
  await built.connect()
  try {
    const one = built.kayan.placedNotes
    assert.deepEqual(Object.keys(one).sort(), ['fields', 'name', 'operations', 'targets'])
    assert.equal(one.name, 'placedNotes')
    assert.deepEqual(Object.keys(one.fields), ['id', 'title'])
    assert.equal(one.operations, one.targets.service.operations, 'the root shortcut is the service target\'s own object')
    assert.ok(Object.isFrozen(one), 'the published namespace is frozen')
    assert.ok(Object.isFrozen(one.operations), 'and so is the operations container')
    assert.equal(typeof (notes.targets.service.operations as Record<string, unknown>).shout, 'object')
    assert.equal(typeof one.operations.shout, 'function')
    await one.operations.create({ id: 'n1', title: 'One' })
    assert.equal((await one.targets.service.operations.findByID({ id: 'n1' }))?.title, 'One')
    assert.equal((await one.operations.count()).totalDocs, 1)
  } finally {
    await built.destroy()
  }
})

