test('149. registration order changes no selection: the service target may be declared before the store and the schema target it names, and the rows land in the same places either way', async () => {
  // Four of the capabilities the template declares (a store, a schema target, the access
  // target and the runner), with a second store and a second schema target beside them,
  // because an order that changed a selection would otherwise have nothing to change it to.
  // Each build gets an adapter and role kayan of its own, so nothing here renames a table
  // the template's own target reads.
  const build = (runnerFirst: boolean) => {
    const service = serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'drizzle', schema: 'zod', authorize: defaultAuthorize })
    const rest = {
      drizzle: drizzleAdapter({ db, kinds: drizzleKinds, rules: drizzleRules }),
      zod: { ...zodTarget, kinds: zodKinds, rules: zodRules },
      memory: memoryStore(),
      plain: plainTarget,
      rbac: rbacTarget({
        roles: {},
        rolesOf: () => [],
        kayan: { roles: 'orderedRoles', memberRoles: 'orderedMemberRoles' },
      }),
    }
    const language = defineMithaq({
      arkan: [base],
      // One object in two key orders, which is the whole of what this test
      // varies: every other key keeps its place.
      targets: runnerFirst ? { service, ...rest } : { ...rest, service },
    })
    return language.buildAsas({
      http: [fetchHttp()],
      kayan: [
        language.defineKayan({
          name: 'orderedRows',
          dbName: 'ordered_rows',
          access: allowAccess,
          fields: { ...defaultFields, title: { kind: 'text', label: { en: 'Title', ar: 'العنوان' } } },
          targets: { service: { operations: defaultOperations } },
        }),
        // The kayan that names its own store and its own schema target, so an
        // order that resolved either one differently would land its rows in
        // another database.
        language.defineKayan({
          name: 'orderedLoose',
          access: allowAccess,
          targets: { service: { store: 'memory', schema: 'plain', operations: defaultOperations } },
          fields: { id: { kind: 'text', label: { en: 'ID', ar: 'المعرف' } }, title: { kind: 'text', label: { en: 'Title', ar: 'العنوان' } } },
        }),
        language.defineKayan({
          name: 'orderedRoles',
          dbName: 'ordered_roles',
          access: allowAccess,
          fields: { ...defaultFields, name: { kind: 'text' }, permissions: { kind: 'textArray' }, isSystem: { kind: 'checkbox' } },
          targets: { service: { operations: defaultOperations } },
        }),
        language.defineKayan({
          name: 'orderedMemberRoles',
          dbName: 'ordered_member_roles',
          access: allowAccess,
          fields: { ...defaultFields, user: { kind: 'text' }, role: { kind: 'text' }, tenant: { kind: 'text' } },
          targets: { service: { operations: defaultOperations } },
        }),
      ],
    })
  }
  const first = build(true)
  const last = build(false)
  await first.connect()
  await last.connect()
  try {
    // What each kayan selected, read off the keys it publishes: a target's
    // output is there under the name that kayan selected and nowhere else, so
    // these key sets are the effective store and the effective schema target
    // said out loud.
    assert.deepEqual(Object.keys(first.kayan.orderedRows.targets).sort(), ['drizzle', 'service', 'zod'])
    assert.deepEqual(Object.keys(first.kayan.orderedLoose.targets).sort(), ['plain', 'service'])
    for (const name of ['orderedRows', 'orderedLoose'] as const) {
      assert.deepEqual(
        Object.keys(last.kayan[name].targets).sort(),
        Object.keys(first.kayan[name].targets).sort(),
        `${name} selects the same store and the same schema target whichever order the runner was declared in`,
      )
      assert.deepEqual(Object.keys(last.kayan[name].operations).sort(), Object.keys(first.kayan[name].operations).sort())
    }
    // And the rows land in the same places. The kayan on the default store
    // writes through drizzle in both builds, so the row one build wrote is the
    // row the other reads back out of the one table they both selected.
    const made = await first.kayan.orderedRows.operations.create({ title: 'Runner declared first' })
    assert.equal(
      (await last.kayan.orderedRows.operations.findByID({ id: made.id }))?.title,
      'Runner declared first',
      'the build that declared its runner last reads the row out of the same table',
    )
    // The kayan that named the memory store writes there in both builds, and a
    // memory store is one build's own, so each sees its own row and neither
    // sees the other's. A build that had resolved this kayan to drizzle instead
    // would answer the row here.
    await first.kayan.orderedLoose.operations.create({ id: 'loose-1', title: 'In memory' })
    assert.equal((await first.kayan.orderedLoose.operations.findByID({ id: 'loose-1' }))?.title, 'In memory')
    await assert.rejects(
      () => last.kayan.orderedLoose.operations.findByID({ id: 'loose-1' }),
      notFound,
      'a kayan naming the memory store writes to that build\'s own memory and to no shared table',
    )
  } finally {
    await first.destroy()
    await last.destroy()
  }
})

test('150. a build publishes its resolved declarations off its public shape, which is where a kayan\'s store is read now', () => {
  // The seam `mithaq rbac assign` reads: a built kayan publishes `name`, `fields`,
  // `operations` and `targets` and no configuration, so the store a kayan is written
  // through is here and nowhere on the object a caller holds.
  const declarations = resolvedKayans.get(asas)
  assert.ok(declarations, 'the build is in the map')
  assert.deepEqual(
    Object.keys(declarations).sort(),
    [...Object.keys(asas.kayan), ...Object.keys(asas.global)].sort(),
    'every kayan and every global of the build is named, under its own name',
  )
  assert.ok(Object.isFrozen(declarations), 'and the record is frozen, so nothing can add a kayan to it')
  assert.equal(declarations.courses!.store, 'drizzle', 'each carries the store it is written through')
  assert.equal(declarations.memberRoles!.store, 'drizzle', 'which is what the assignment command compares')
  assert.equal(declarations.courses!.table, 'courses', 'and the table that store writes it to')
  assert.deepEqual(Object.keys(asas.kayan.courses).sort(), ['fields', 'name', 'operations', 'targets'])
  assert.equal((asas.kayan.courses as unknown as { store?: unknown }).store, undefined)
})

/**
 * A kayan's operations are exactly what its file declares: the service target holds none,
 * nothing is merged in, and `false` is no operation value. A kayan that wants the shipped
 * lists spreads `defaultOperations` into its own `targets.service.operations`, the way it
 * spreads `defaultFields` into its `fields`.
 */
test('151. a kayan that declares no operations answers none, and one that spreads the shipped lists answers exactly those', () => {
  const language = offline()
  const bare = language.defineKayan({ name: 'bare', fields: { id: defaultFields.id, title: { kind: 'text' } } })
  const spread = language.defineKayan({
    name: 'spread',
    fields: { id: defaultFields.id, title: { kind: 'text' } },
    targets: { service: { operations: { ...defaultOperations } } },
  })
  const built = language.buildAsas({ http: [fetchHttp()], kayan: [bare, spread] })
  assert.deepEqual(Object.keys(built.kayan.bare.operations), [], 'a kayan that declares none answers no operation')
  assert.deepEqual(built.statements.bare, ['fields.id', 'fields.title'], 'and the catalog names no operation of it')
  assert.deepEqual(Object.keys(built.kayan.spread.operations).sort(), Object.keys(defaultOperations).sort())
})

