test('155. a global is one row for the project unless it places the tenant field, and a column called tenant places none', () => {
  const language = offline()
  // The column that keeps the row single is `globalType` here: a global placing the tenant
  // field is `tenant-target.test.ts`'s, one row per organization.
  const oneRow = (fields: Record<string, unknown>) => () =>
    language.buildAsas({
      http: [fetchHttp()],
      kayan: [],
      global: [
        language.defineGlobal({
          name: 'oneRow',
          access: { read: () => true, update: () => true },
          fields: { ...defaultFields, ...fields } as never,
          targets: { service: { operations: defaultGlobalOperations } },
        }),
      ],
    })
  const tenant = { kind: 'text', rules: { required: true, unique: true } } as const
  assert.doesNotThrow(oneRow({ tenant, ...defaultGlobalFields }), 'a unique globalType keeps it one row, a column called tenant beside it')
  for (const fields of [{ tenant, globalType: { ...defaultGlobalFields.globalType, rules: { required: true } } }, { globalType: { ...defaultGlobalFields.globalType, rules: { required: true } } }]) {
    assert.throws(
      oneRow(fields),
      /Global "oneRow" declares no tenant and a "globalType" that is not unique, so two first updates would leave two rows\./,
      'and a globalType that is not unique is refused, whatever a column is called',
    )
  }
  // Written as plain data, the one way a global reaches indexes: dropping its unique index is refused.
  const plain = { ...language.defineGlobal({ name: 'oneRow', fields: { ...defaultFields, ...defaultGlobalFields }, targets: { service: { operations: defaultGlobalOperations } } }), indexes: () => [{ fields: ['globalType', 'id'], unique: true }] }
  assert.throws(
    () => language.buildAsas({ http: [fetchHttp()], kayan: [], global: [plain as never] }),
    /^Error: Global "oneRow" builds no unique index over "globalType" alone, and that index is what keeps the global to one row\. Keep it in indexes\.$/,
  )
})

test('156. a kayan, field or operation named for what Object.prototype carries builds, serves its routes, generates its messages and gets its table', async () => {
  const language = defineMithaq({
    locales: ['ar', 'en'] as const,
    arkan: [base],
    targets: {
      drizzle: drizzleAdapter({ db, kinds: drizzleKinds, rules: drizzleRules }),
      zod: { ...zodTarget, kinds: zodKinds, rules: zodRules },
      service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'drizzle', schema: 'zod', authorize: defaultAuthorize }),
    },
  })
  // A field named `__proto__` is refused at build instead.
  const operations = { ...defaultOperations, constructor: defaultOperations.create }
  const built = language.buildAsas({
    kayan: [
      language.defineKayan({
        name: 'constructor',
        access: allowAccess,
        fields: {
          ...defaultFields,
          title: { kind: 'text' },
          toString: { kind: 'text', label: { ar: 'نصا', en: 'As text' } },
        },
        targets: { service: { operations } },
      }),
      language.defineKayan({
        name: 'toString',
        access: allowAccess,
        fields: { ...defaultFields, title: { kind: 'text' } },
        targets: { service: { operations } },
      }),
    ],
    http: [fetchHttp(), orpcHttp({ api: '/api/orpc' })],
  })
  await db.execute('drop table if exists "constructor", "toString"')
  await built.connect()
  try {
    assert.deepEqual(
      (await columnsOf('constructor')).sort(),
      ['created_at', 'id', 'title', 'to_string', 'updated_at'],
      'the table and every column are created under their own names',
    )
    assert.ok((await columnsOf('toString')).includes('title'))
    for (const kayan of ['constructor', 'toString']) {
      for (const [prefix, operation] of [['/api', 'create'], ['/api/orpc', 'create'], ['/api', 'constructor'], ['/api/orpc', 'constructor']]) {
        const response = await posted(built, `${prefix}/${kayan}/${operation}`, { title: `${kayan} ${operation}` })
        assert.equal(response.status, 200, `${prefix}/${kayan}/${operation} is served: ${await response.clone().text()}`)
        const body = (await response.json()) as Record<string, unknown>
        assert.equal(((body.json ?? body) as { title?: unknown }).title, `${kayan} ${operation}`)
      }
    }
    const row = await posted(built, '/api/constructor/create', { title: 'odd', toString: 'a' })
    assert.equal(row.status, 200)
    assert.equal(((await row.json()) as Record<string, unknown>).toString, 'a')
    assert.ok(built.operations.some((one) => one.kayan === 'toString' && one.name === 'constructor'))
    const unknown = await posted(built, '/api/toString/find', { where: { hasOwnProperty: { equals: 'x' } } })
    assert.equal(unknown.status, 400, `a query naming a key of Object.prototype no field declares is refused: ${await unknown.clone().text()}`)
    const directory = pathToFileURL(`${await mkdtemp(join(tmpdir(), 'mithaq-prototype-'))}/`)
    try {
      await generateMessages({ registry: built.messages, directory })
      assert.deepEqual(refusals(await generateMessages({ registry: built.messages, directory, check: true })), [])
      const written = JSON.parse(await readFile(new URL('constructor.json', directory), 'utf8')) as Record<string, unknown>
      assert.deepEqual(written.toString, { ar: 'نصا', en: 'As text' }, 'the label is written under the field name')
      assert.ok(Object.hasOwn(written, 'toString.invalid'))
    } finally {
      await rm(directory, { recursive: true })
    }
  } finally {
    await built.destroy()
  }
})

