test('158. first-register drains the create\'s afterCommit once its transaction has committed, and a first-register the transaction throws inside drains it zero times', async () => {
  const language = online()
  const committedCalls: string[] = []
  const recordAfterCommit: WriteStep = (ctx) => {
    committedCalls.push('afterCommit')
    return ctx
  }
  const okName = 'afterCommitFirstRegisterUsers'
  const okKayan = language.defineKayan({
    name: okName,
    dbName: 'after_commit_first_register_users',
    access: allowAccess,
    fields: { ...defaultFields, ...localAuthFields },
    targets: { service: { operations: { ...localOperations, create: { ...localAuthOperations.create, afterCommit: [recordAfterCommit] } } } },
  })
  const okBuilt = language.buildAsas({ http: [fetchHttp()], kayan: [authenticating(okKayan, local({ ...localRequired, secret: `${okName}-secret-of-thirty-two-characters` }))] })
  await okBuilt.connect()
  try {
    const response = await call(okBuilt, 'first-register', {
      method: 'POST',
      body: JSON.stringify({ email: `${okName}@example.com`, password: 'a-long-enough-password' }),
    })
    assert.equal(response.status, 201)
    assert.deepEqual(committedCalls, ['afterCommit'], 'the afterCommit step ran exactly once, after the commit')
  } finally {
    await okBuilt.destroy()
  }

  // A step the create's own list holds throws before the store step, which
  // fails the transaction first-register opened, so the row it would have made
  // is never there and the afterCommit step it lists never runs.
  const failedCalls: string[] = []
  const boom: WriteStep = () => {
    throw new Error('first-register boom')
  }
  const failName = 'afterCommitFailingFirstRegisterUsers'
  const failKayan = language.defineKayan({
    name: failName,
    dbName: 'after_commit_failing_first_register_users',
    access: allowAccess,
    fields: { ...defaultFields, ...localAuthFields },
    targets: {
      service: {
        operations: {
          ...localOperations,
          create: {
            ...localAuthOperations.create,
            steps: [boom, ...localAuthOperations.create.steps],
            afterCommit: [(ctx: Ctx) => { failedCalls.push('afterCommit'); return ctx }],
          },
        },
      },
    },
  })
  const failBuilt = language.buildAsas({ http: [fetchHttp()], kayan: [authenticating(failKayan, local({ ...localRequired, secret: `${failName}-secret-of-thirty-two-characters` }))] })
  await failBuilt.connect()
  try {
    await assert.rejects(
      call(failBuilt, 'first-register', {
        method: 'POST',
        body: JSON.stringify({ email: `${failName}@example.com`, password: 'a-long-enough-password' }),
      }),
      /first-register boom/,
    )
    assert.deepEqual(failedCalls, [], 'a first-register the transaction threw inside drains no afterCommit')
    assert.equal(
      (await failBuilt.targets.drizzle.db.select().from(failBuilt.targets.drizzle.tables[failKayan.name]!)).length,
      0,
      'no row stands for the failed attempt',
    )
  } finally {
    await failBuilt.destroy()
  }
})

/**
 * Who may enter a screen. Every screen has a catalog key, `screen.<name>`, derived the way
 * `<kayan>.<operation>` is, and a role holds it like any other key: `'*'` enters every
 * screen, a tenant's custom role holding one enters that one, and the granter guard stops
 * a role handing out a screen its author cannot enter. The report lists the screens and
 * the data API does not ask.
 */
test('159. a screen is entered only with its screen.<name> key: \'*\' enters both, a custom role holding screen.portal enters only the portal, the granter guard holds, and the data API never asks', async () => {
  assert.deepEqual(asas.catalog.filter((key) => key.startsWith('screen.')), ['screen.dashboard', 'screen.portal', 'screen.platform'], 'one key per screen of the template and no other')
  const report = async (headers?: Headers) =>
    (await (await asas.handler(new Request('http://test/api/access', headers ? { headers } : {}))).json()) as { screens: string[] }
  assert.deepEqual((await report()).screens, [], 'an anonymous report names no screen')

  const signUp = await server.api.signUpEmail({
    body: { name: 'Gatekeeper', email: 'gatekeeper@example.com', password: 'a-long-enough-password' },
    returnHeaders: true,
  })
  const ownerHeaders = new Headers({ cookie: signUp.headers.get('set-cookie') ?? '' })
  const organization = await server.api.createOrganization({ body: { name: 'Gate Tenant', slug: 'gate-tenant' }, headers: ownerHeaders })
  const owner = await asas.auth.actor(ownerHeaders)
  assert.ok(owner)
  // `'*'` is every key inside the tenant, the platform screen's among them, which the tenant
  // app serves no route for; the platform app answers no membership role, so the same
  // person holds nothing there.
  assert.deepEqual((await report(ownerHeaders)).screens, ['dashboard', 'portal', 'platform'], "the tenant's administrator holds '*' inside its tenant")
  assert.deepEqual((await asPlatform(async () => report((await onPlatform(ownerHeaders))))).screens, [], 'and enters nothing in the platform app')

  const roleKeys = asas.catalog.filter((key) => key.startsWith('roles.'))
  await asas.kayan.roles.operations.create({ name: 'porter', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['screen.portal', 'courses.find', 'courses.fields.title', ...roleKeys] }, { actor: owner as never })
  const unknown = await asas.kayan.roles.operations
    .create({ name: 'nowhere', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['screen.nowhere'] }, { actor: owner as never })
    .catch((thrown: unknown) => thrown)
  assert.ok(unknown instanceof AsasError && unknown.status === 400, 'a screen key the build derives no screen for is refused as a key outside the catalog')
  assert.match(unknown.message, /Permission "screen\.nowhere" is not a key of this project's catalog\. A key is "<kayan>\.<operation>", "<kayan>\.fields\.<field>" or "screen\.<screen>"\./)

  const member = async (name: string, role: string) => {
    const made = await server.api.signUpEmail({ body: { name, email: `${name}@example.com`, password: 'a-long-enough-password' }, returnHeaders: true })
    const headers = new Headers({ cookie: made.headers.get('set-cookie') ?? '' })
    await server.api.addMember({ body: { userId: made.response.user.id, organizationId: organization!.id, role: 'member' } })
    await server.api.setActiveOrganization({ body: { organizationId: organization!.id }, headers })
    await assignRole(organization!.id, made.response.user.id, role)
    return headers
  }
  const porterHeaders = await member('porter', 'porter')
  assert.deepEqual((await report(porterHeaders)).screens, ['portal'], 'a member holding screen.portal enters the portal and not the dashboard')

  // The granter guard is the one every key goes through: the porter may hand
  // on the portal it enters and not the dashboard it does not.
  const porter = await asas.auth.actor(porterHeaders)
  const escalation = await asas.kayan.roles.operations
    .create({ name: 'usher', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['screen.dashboard'] }, { actor: porter as never })
    .catch((thrown: unknown) => thrown)
  assert.ok(escalation instanceof AsasError && escalation.status === 403, 'granting a screen the granter does not hold is refused 403')
  assert.equal(escalation.key, 'error.forbidden.grant', 'under the granter guard')
  const usher = await asas.kayan.roles.operations.create({ name: 'usher', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['screen.portal'] }, { actor: porter as never })
  assert.deepEqual(usher.permissions, ['screen.portal'], 'and granting one it holds is written')

  // A member holding a kayan key and no screen key enters no screen, and the
  // data API answers it exactly as before: the gate is the screen's.
  await asas.kayan.roles.operations.create({ name: 'finder', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: owner as never })
  const readerHeaders = await member('finder', 'finder')
  const found = await asas.handler(new Request('http://test/api/courses/find', { method: 'POST', headers: new Headers({ cookie: readerHeaders.get('cookie')!, 'content-type': 'application/json' }), body: '{}' }))
  assert.equal(found.status, 200, 'a member holding courses.find and no screen key reads the kayan through the data API')
  assert.deepEqual((await report(readerHeaders)).screens, [], 'while entering no screen')
})

/**
 * A build with no access target has no key to read, so the floor is: the actor of the
 * kayan `auth.admin` names, for which `auth.admin.access` answers yes, enters every
 * screen, and nobody else enters any.
 */
test('160. without an access target, only the auth.admin actor its access admits enters a screen', async () => {
  const shell = { controls: screenKinds, providers: [], layouts: {}, components: {} }
  const home = (ui: typeof dashboardUi, file: `${string}#${string}`) => ({ home: { path: '/', component: ui(file) } })
  const language = defineMithaq({
    arkan: [base],
    targets: {
      drizzle: drizzleAdapter({ db, kinds: drizzleKinds, rules: drizzleRules }),
      zod: { ...zodTarget, kinds: zodKinds, rules: zodRules },
      service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'drizzle', schema: 'zod', authorize: defaultAuthorize, afterSteps: [] }),
      dashboard: screenTarget({ ...shell, path: '/dashboard', kayan: [], pages: home(dashboardUi, 'dashboard.tsx#Dashboard') }),
      portal: screenTarget({ ...shell, path: '/portal', kayan: [], pages: home(portalUi, 'home.tsx#Home') }),
    },
  })
  const kayan = language.defineKayan({
    name: 'screenLocalUsers',
    dbName: 'screen_local_users',
    access: { create: () => true, read: () => false, update: () => false, delete: () => false },
    fields: { ...localAuthFields } as typeof localAuthFields,
    targets: { service: { operations: localOperations } },
  })
  let admitted = true
  const authenticated = authenticating(kayan, local({ ...localRequired, secret: 'screen-local-secret-of-thirty-two-characters' }))
  const built = language.buildAsas({ http: [fetchHttp()], kayan: [authenticated], auth: { admin: { kayan: authenticated, access: () => admitted }, onError: console.error } })
  await built.connect()
  try {
    const screens = async (cookie?: string) =>
      ((await (await built.handler(new Request('http://test/api/access', cookie ? { headers: { cookie } } : {}))).json()) as { screens: string[] }).screens
    const { cookie } = await firstAccount(built, 'screen-admin@example.com')
    assert.deepEqual(await screens(cookie), ['dashboard', 'portal'], 'the admin actor its access admits enters every screen')
    admitted = false
    assert.deepEqual(await screens(cookie), [], 'and the same actor enters none once auth.admin.access says no')
    assert.deepEqual(await screens(), [], 'and nobody without a session enters any')
  } finally {
    await built.destroy()
  }
})

/**
 * The derived nav as each actor sees it: each kayan's list page, and a single's one page,
 * behind the read it needs, in the order the screen lists its kayan, cut to the keys the
 * actor's own report says it holds.
 */
test('161. the derived nav lists exactly the entries each actor may open, in declaration order: every one for the tenant\'s administrator, courses and tags for a member holding their keys', async () => {
  const report = async (headers: Headers) => (await (await asas.handler(new Request('http://test/api/access', { headers }))).json()) as AccessReport
  const client = asas.targets.dashboard.client
  const signUp = await server.api.signUpEmail({
    body: { name: 'Navigator', email: 'navigator@example.com', password: 'a-long-enough-password' },
    returnHeaders: true,
  })
  const ownerHeaders = new Headers({ cookie: signUp.headers.get('set-cookie') ?? '' })
  const organization = await server.api.createOrganization({ body: { name: 'Nav Tenant', slug: 'nav-tenant' }, headers: ownerHeaders })
  const owner = await asas.auth.actor(ownerHeaders)
  assert.deepEqual(
    navOf(client, await report(ownerHeaders)).map((entry) => entry.path),
    // No '/member-roles': a member's roles are changed on the members page.
    ['/courses', '/sessions', '/enrollments', '/tags', '/media', '/roles', '/settings', '/members'],
    "the tenant's administrator holds '*' and sees every entry, in the screen's kayan order, then the screen's own page",
  )

  await asas.kayan.roles.operations.create({ name: 'browser', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['screen.dashboard', 'tags.find', 'tags.fields.id', 'courses.find', 'courses.fields.title'] }, { actor: owner as never })
  const made = await server.api.signUpEmail({ body: { name: 'browser', email: 'browser@example.com', password: 'a-long-enough-password' }, returnHeaders: true })
  const headers = new Headers({ cookie: made.headers.get('set-cookie') ?? '' })
  await server.api.addMember({ body: { userId: made.response.user.id, organizationId: organization!.id, role: 'member' } })
  await server.api.setActiveOrganization({ body: { organizationId: organization!.id }, headers })
  await assignRole(organization!.id, made.response.user.id, 'browser')
  assert.deepEqual(
    navOf(client, await report(headers)).map((entry) => entry.path),
    ['/courses', '/tags'],
    'a member holding courses.find and tags.find sees those two, in declaration order and not in the order the role wrote them',
  )
})

/**
 * The server side of `options`: the zod target shapes a field carrying `options` as
 * `z.enum(values)`, or an array of that enum for `textArray`, and the template's
 * standard-schema target does the same.
 */
test('162. a create and an update carrying a value outside a field\'s options are refused 400 under the field\'s invalid key, over HTTP, for a text field and a textArray field, on either schema target', async () => {
  const optionFields = {
    id: { kind: 'text' as const },
    status: {
      kind: 'text' as const,
      options: [
        { value: 'draft', label: {} },
        { value: 'live', label: {} },
      ],
    },
    tags: {
      kind: 'textArray' as const,
      options: [
        { value: 'a', label: {} },
        { value: 'b', label: {} },
      ],
    },
  }
  const issuesOf = async (response: Response) =>
    ((await response.json()) as { data: { params: { issues: { path: string; message: string }[] } } }).data.params.issues

  for (const schema of ['zod', 'plain'] as const) {
    const language = defineMithaq({
      arkan: [base],
      targets: {
        memory: memoryStore(),
        zod: zodTarget,
        plain: plainTarget,
        service: serviceTarget({ depth: defaultDepth, defaultLimit, maxLimit: defaultMaxLimit, joinLimit: defaultJoinLimit, bulkLimit: defaultBulkLimit, store: 'memory', schema, authorize: defaultAuthorize }),
      },
    })
    const kayan = language.defineKayan({
      name: 'optionRows',
      access: allowAccess,
      fields: optionFields,
      targets: { service: { operations: defaultOperations } },
    })
    const built = language.buildAsas({ http: [fetchHttp()], kayan: [kayan] })
    await built.connect()

    const badStatus = await posted(built, '/api/optionRows/create', { id: '1', status: 'archived', tags: ['a'] })
    assert.equal(badStatus.status, 400, `${schema}: a status outside options is a 400 on create`)
    assert.deepEqual(
      await issuesOf(badStatus),
      [{ path: 'status', message: 'optionRows.status.invalid' }],
      `${schema}: refused under the text field's own invalid key`,
    )

    const badTags = await posted(built, '/api/optionRows/create', { id: '1', status: 'draft', tags: ['a', 'z'] })
    assert.equal(badTags.status, 400, `${schema}: a tags element outside options is a 400 on create`)
    const tagsIssues = await issuesOf(badTags)
    assert.equal(tagsIssues.length, 1, `${schema}: one issue for the one bad element`)
    assert.equal(tagsIssues[0]!.message, 'optionRows.tags.invalid', `${schema}: refused under the textArray field's own invalid key`)
    assert.ok(tagsIssues[0]!.path.startsWith('tags'), `${schema}: at the tags field, element index or not`)

    const made = await posted(built, '/api/optionRows/create', { id: '1', status: 'draft', tags: ['a', 'b'] })
    assert.equal(made.status, 200, `${schema}: a value inside options is accepted on create`)

    const badUpdate = await posted(built, '/api/optionRows/update', { id: '1', status: 'archived' })
    assert.equal(badUpdate.status, 400, `${schema}: a status outside options is a 400 on update`)
    assert.deepEqual(
      await issuesOf(badUpdate),
      [{ path: 'status', message: 'optionRows.status.invalid' }],
      `${schema}: refused under the field's own invalid key on update too`,
    )

    const okUpdate = await posted(built, '/api/optionRows/update', { id: '1', status: 'live', tags: ['b'] })
    assert.equal(okUpdate.status, 200, `${schema}: a value inside options is accepted on update`)

    await built.destroy()
  }
})

test('163. a new password is stored with its scrypt parameters, at N=2^17, and signs in', async () => {
  const { built, kayan } = await localAuthProject('paramLocalUsers')
  try {
    await firstAccount(built, 'params@example.com')
    const [row] = await built.targets.drizzle.db.select().from(built.targets.drizzle.tables[kayan.name]!) as Record<string, unknown>[]
    assert.match(String(row!.hash), /^scrypt\$131072\$8\$1\$[\w-]{86}$/, 'N, r and p ride in front of the hash')
    assert.equal((await login(built, 'params@example.com', 'a-long-enough-password')).status, 200)
  } finally {
    await built.destroy()
  }
})

test('164. a hash stored without parameters still signs in and is rehashed at the current ones on that login, and a wrong password never rehashes it', async () => {
  const { built, kayan } = await localAuthProject('legacyLocalUsers')
  const { db, tables } = built.targets.drizzle
  const table = tables[kayan.name]!
  const stored = async () => (await db.select().from(table))[0] as Record<string, unknown>
  try {
    await firstAccount(built, 'legacy@example.com')
    // The row as a build that stored no parameters wrote it: scrypt at Node's defaults,
    // N=16384, r=8, p=1, and the bare hash.
    const salt = crypto.randomBytes(16).toString('base64url')
    const legacy = crypto.scryptSync('an-older-password', salt, 64).toString('base64url')
    await db.update(table).set({ hash: legacy, salt })

    assert.equal((await login(built, 'legacy@example.com', 'the-wrong-password')).status, 401)
    assert.equal((await stored()).hash, legacy, 'a wrong password leaves the old hash')
    assert.equal((await stored()).salt, salt)

    assert.equal((await login(built, 'legacy@example.com', 'an-older-password')).status, 200)
    const upgraded = await stored()
    assert.match(String(upgraded.hash), /^scrypt\$131072\$8\$1\$[\w-]{86}$/, 'rehashed at the current parameters')
    assert.notEqual(upgraded.salt, salt, 'with a fresh salt')
    assert.equal((await login(built, 'legacy@example.com', 'an-older-password')).status, 200, 'and the new hash signs in')
    assert.equal((await stored()).hash, upgraded.hash, 'a current hash is not rehashed again')
  } finally {
    await built.destroy()
  }
})

test('165. an unknown address costs one scrypt at the current parameters, the same as a wrong password for a known one', async () => {
  const { built } = await localAuthProject('costLocalUsers')
  try {
    await firstAccount(built, 'known@example.com')
    const spy = mock.method(crypto, 'scrypt')
    try {
      for (const email of ['nobody@example.com', 'known@example.com']) {
        spy.mock.resetCalls()
        assert.equal((await login(built, email, 'the-wrong-password')).status, 401)
        assert.equal(spy.mock.callCount(), 1, `${email} runs scrypt once`)
        assert.equal((spy.mock.calls[0]!.arguments[3] as { N: number }).N, 2 ** 17, `${email} runs it at N=2^17`)
      }
    } finally {
      spy.mock.restore()
    }
  } finally {
    await built.destroy()
  }
})

test('166. a stored hash naming any cost but the current one or Node\'s defaults is a wrong password, refused before scrypt runs at that cost', async () => {
  const { built, kayan } = await localAuthProject('boundedLocalUsers')
  const { db, tables } = built.targets.drizzle
  try {
    await firstAccount(built, 'bounded@example.com')
    // p costs time and almost no memory, so this fits under maxmem and would
    // hold a threadpool thread for about a day.
    await db.update(tables[kayan.name]!).set({ hash: 'scrypt$524288$2$524288$x' })
    const original = crypto.scrypt
    const spy = mock.method(crypto, 'scrypt', (...args: unknown[]) => {
      const options = args[3] as { N: number; p: number }
      const done = args[4] as (error: Error | null, key?: Buffer) => void
      if (options.N !== 2 ** 17 && options.N !== 16384) return done(new Error('scrypt ran at a stored cost outside the allow-list'))
      if (options.p !== 1) return done(new Error('scrypt ran at a stored cost outside the allow-list'))
      return (original as (...rest: unknown[]) => void)(...args)
    })
    try {
      const started = Date.now()
      assert.equal((await login(built, 'bounded@example.com', 'a-long-enough-password')).status, 401, 'answered as a wrong password')
      assert.ok(Date.now() - started < 5000, 'and promptly')
      assert.equal(spy.mock.callCount(), 1, 'one scrypt, the same as an unknown address')
      assert.deepEqual(spy.mock.calls[0]!.arguments[3], { N: 2 ** 17, r: 8, p: 1, maxmem: 256 * 1024 * 1024 }, 'at the current cost')
    } finally {
      spy.mock.restore()
    }
  } finally {
    await built.destroy()
  }
})

test('167. once buildAsas returns, every record mithaq built is frozen deep, a write to one throws, and the library objects it holds are left alone', () => {
  const refused = (write: () => void, path: string) => assert.throws(write, TypeError, path)
  const declaredLevel = coursesDeclaration.fields.level as unknown as { rules: Record<string, unknown> }
  refused(() => { declaredLevel.rules.min = 0 }, 'the declared export\'s field rules')
  const course = asas.kayan.sessions.fields.course as unknown as { target: { operations: Record<string, unknown> } }
  refused(() => { course.target.operations.find = () => [] }, 'fields.<rel>.target.operations')
  const find = course.target.operations.find as { steps: unknown[] }
  refused(() => { find.steps.push(() => undefined) }, 'an operation declaration\'s steps')
  const currency = asas.kayan.courses.fields.currency as unknown as { options: { value: string }[] }
  refused(() => { currency.options[0]!.value = 'EUR' }, 'asas.kayan.<x>.fields.<f>.options')
  refused(() => { currency.options.push({ value: 'EUR' }) }, 'and the list itself')
  const table = asas.operations as unknown as { name: string }[]
  refused(() => { table.push({ name: 'stray' }) }, 'the operation table')
  refused(() => { table[0]!.name = 'stray' }, 'and each of its entries')
  const client = asas.targets.dashboard.client
  refused(() => { client.nav.push({ path: '/stray', page: 'stray' } as never) }, 'a screen projection')
  refused(() => { client.path = '/stray' }, 'and its root')
  refused(() => { (asas.kayan as Record<string, unknown>).stray = {} }, 'the built kayan record')

  // What a library built is its own, and freezing it would break it.
  assert.equal(Object.isFrozen(asas.kayan.courses.targets.drizzle.table), false, 'a drizzle table')
  assert.equal(Object.isFrozen(asas.targets.drizzle.db), false, 'the drizzle db')
  assert.equal(Object.isFrozen(asas.kayan.courses.targets.zod.schemas.create), false, 'a derived zod schema')
  assert.equal(Object.isFrozen(asas.operations[0]!.input), false, 'an operation\'s input schema')
  const fee = asas.kayan.courses.fields.fee as unknown as { targets: { zod: object } }
  assert.equal(Object.isFrozen(fee.targets.zod), false, 'a field\'s own zod override')
  assert.ok(Object.isFrozen(fee.targets), 'while the bag holding it is frozen')
  assert.equal(fee.targets.zod, (coursesDeclaration.fields.fee as unknown as { targets: { zod: object } }).targets.zod, 'and is the object the declaration wrote')
})

test('168. the records the build leaves open are frozen shallow: the asas root, asas.auth, the strategy list and the targets map, and nothing inside them', () => {
  const refused = (write: () => void, path: string) => assert.throws(write, TypeError, path)
  const open = asas as unknown as Record<string, unknown> & { auth: Record<string, unknown> & { strategies: unknown[] }; targets: Record<string, unknown> }
  refused(() => { open.auth.strategies.push({ name: 'fake', authenticate: async () => ({ user: {} }) }) }, 'asas.auth.strategies')
  refused(() => { open.handler = async () => new Response('stray') }, 'asas.handler')
  refused(() => { open.auth.actor = async () => ({}) }, 'asas.auth.actor')
  refused(() => { open.targets.dashboard = {} }, 'asas.targets.dashboard')
  assert.equal(Object.isFrozen(asas.auth.strategies[0]), false, 'a strategy object is the provider\'s')
  assert.equal(Object.isFrozen(asas.targets.drizzle), false, 'and a target is the language\'s')
  assert.equal(Object.isFrozen(asas.router), false, 'and the router is the plug\'s')
})

/** The address a test request says it came from, read the way a project reads its own trusted proxy's header. */
const testIp = (request: Request) => request.headers.get('x-test-ip')
const loginFrom = (built: { handler(request: Request): Promise<Response> }, ip: string, email: string, password: string) =>
  call(built, 'login', { method: 'POST', headers: { 'x-test-ip': ip }, body: JSON.stringify({ email, password }) })

test('169. past ten requests a minute from one address, login, forgot-password and reset-password answer 429 at once and run no scrypt', async () => {
  const { built } = await localAuthProject('burstLocalUsers', { ip: testIp })
  const from = (path: string, body: unknown) =>
    call(built, path, { method: 'POST', headers: { 'x-test-ip': '203.0.113.1' }, body: JSON.stringify(body) })
  try {
    for (let index = 0; index < 4; index++) assert.equal((await loginFrom(built, '203.0.113.1', `nobody${index}@example.com`, 'the-wrong-password')).status, 401)
    for (let index = 0; index < 3; index++) assert.equal((await from('forgot-password', { email: `nobody${index}@example.com` })).status, 200)
    for (let index = 0; index < 3; index++) assert.equal((await from('reset-password', { token: 'unknown', password: 'a-long-enough-password' })).status, 400)
    const spy = mock.method(crypto, 'scrypt')
    try {
      const started = Date.now()
      const refused = await loginFrom(built, '203.0.113.1', 'nobody@example.com', 'the-wrong-password')
      assert.equal(refused.status, 429, 'the eleventh login from that address is refused')
      assert.ok(Date.now() - started < 100, 'at once, in less time than one scrypt takes')
      assert.equal(spy.mock.callCount(), 0, 'without running scrypt')
      assert.match(refused.headers.get('retry-after') ?? '', /^\d+$/, 'and says when to try again')
      assert.equal((await from('forgot-password', { email: 'nobody@example.com' })).status, 429, 'forgot-password shares the count')
      assert.equal((await from('reset-password', { token: 'unknown', password: 'a-long-enough-password' })).status, 429, 'and so does reset-password')
      assert.equal(spy.mock.callCount(), 0)
    } finally {
      spy.mock.restore()
    }
  } finally {
    await built.destroy()
  }
})

test('170. during a burst from one address, a login from another address still succeeds, and a request the ip function answers null for is never limited', async () => {
  const { built } = await localAuthProject('otherAddressLocalUsers', { ip: testIp })
  try {
    await firstAccount(built, 'legit@example.com')
    await call(built, `verify/${String(((await built.targets.drizzle.db.select().from(built.targets.drizzle.tables.otherAddressLocalUsers!))[0] as Record<string, unknown>)._verificationToken)}`, { method: 'POST' })
    const [legit, ...burst] = await Promise.all([
      loginFrom(built, '198.51.100.7', 'legit@example.com', 'a-long-enough-password'),
      ...Array.from({ length: 15 }, (_, index) => loginFrom(built, '203.0.113.2', `flood${index}@example.com`, 'the-wrong-password')),
    ])
    assert.equal(legit!.status, 200, 'the login from the other address signs in')
    assert.deepEqual(burst.map((response) => response.status).sort(), [...Array(10).fill(401), ...Array(5).fill(429)].sort(), 'while the burst is cut at ten')

    for (let index = 0; index < 12; index++) {
      const response = await call(built, 'forgot-password', { method: 'POST', body: JSON.stringify({ email: 'nobody@example.com' }) })
      assert.equal(response.status, 200, `a request with no address is not limited (${index + 1})`)
    }
  } finally {
    await built.destroy()
  }
})

test('171. within the limit an unknown address and a wrong password answer alike, and each counts the same toward it', async () => {
  const { built } = await localAuthProject('alikeLocalUsers', { ip: testIp, maxLoginAttempts: 100 })
  try {
    await firstAccount(built, 'known@example.com')
    const unknown: Response[] = []
    const wrong: Response[] = []
    for (let index = 0; index < 11; index++) {
      unknown.push(await loginFrom(built, '203.0.113.3', 'nobody@example.com', 'the-wrong-password'))
      wrong.push(await loginFrom(built, '203.0.113.4', 'known@example.com', 'the-wrong-password'))
    }
    for (let index = 0; index < 11; index++) {
      const status = index < 10 ? 401 : 429
      assert.equal(unknown[index]!.status, status, `unknown address, attempt ${index + 1}`)
      assert.equal(wrong[index]!.status, status, `wrong password, attempt ${index + 1}`)
      assert.equal(await unknown[index]!.text(), await wrong[index]!.text(), `in the same words, attempt ${index + 1}`)
    }
  } finally {
    await built.destroy()
  }
})

test('172. the count holds at most ten thousand addresses, so a rotating address set evicts the oldest window rather than growing memory', async () => {
  const { built } = await localAuthProject('boundedMapLocalUsers', { ip: testIp })
  const bodyless = (ip: string) => call(built, 'forgot-password', { method: 'POST', headers: { 'x-test-ip': ip } })
  try {
    for (let index = 0; index < 10; index++) assert.equal((await bodyless('203.0.113.5')).status, 400)
    assert.equal((await bodyless('203.0.113.5')).status, 429, 'the first address is at its limit')
    for (let index = 0; index < 10_000; index++) await bodyless(`10.${index >> 16}.${(index >> 8) & 255}.${index & 255}`)
    assert.equal((await bodyless('203.0.113.5')).status, 400, 'ten thousand other addresses later its window was evicted')
  } finally {
    await built.destroy()
  }
})

test('173. a local() with no ip is refused at build, naming the key, and nothing is warned', () => {
  const language = offline()
  const users = language.defineKayan({ name: 'users', fields: localAuthFields, targets: { service: { operations: localOperations } } })
  const warned: string[] = []
  const warn = console.warn
  console.warn = (...parts: unknown[]) => void warned.push(parts.join(' '))
  try {
    assert.throws(
      () => language.buildAsas({ http: [fetchHttp()], kayan: [authenticating(users, local({ ...localRequired, secret: 'thirty-two-characters-is-enough!', ip: undefined as never }))] }),
      /local\(\{ ip \}\) is required\./,
    )
  } finally {
    console.warn = warn
  }
  assert.deepEqual(warned, [], 'the refusal is the whole answer')
})

test('174. an ip function that answers null tells auth.onError once, the first time, with an Error naming the key, so a limit it switches off is not switched off silently', async () => {
  const heard: unknown[] = []
  const { built } = await localAuthProject('nullIpLocalUsers', { ip: () => null, onError: (error) => void heard.push(error) })
  const warned: string[] = []
  const warn = console.warn
  console.warn = (...parts: unknown[]) => void warned.push(parts.join(' '))
  try {
    for (let index = 0; index < 3; index++) {
      assert.equal((await call(built, 'forgot-password', { method: 'POST', body: JSON.stringify({ email: 'nobody@example.com' }) })).status, 200)
    }
  } finally {
    console.warn = warn
    await built.destroy()
  }
  assert.equal(heard.length, 1, 'told once for three uncounted requests')
  assert.ok(heard[0] instanceof Error, 'as an Error')
  assert.match((heard[0] as Error).message, /local\(\{ ip \}\)/, 'naming the key')
  assert.deepEqual(warned, [], 'and the console hears nothing')
})

test('175. a tenant reads its own members and its own organization, by id, by list and by the picker\'s search, never another tenant\'s, and nothing of either beyond the id and the name', async () => {
  const signUp = async (name: string, email: string) => {
    const made = await server.api.signUpEmail({ body: { name, email, password: 'a-long-enough-password' }, returnHeaders: true })
    return { id: made.response.user.id as string, headers: new Headers({ cookie: made.headers.get('set-cookie') ?? '' }) }
  }
  const asma = await signUp('Asma Owner', 'asma-146@example.com')
  const school = await server.api.createOrganization({ body: { name: 'Asma School', slug: 'asma-school-146' }, headers: asma.headers })
  await assignRole(school!.id, asma.id, 'administrator')
  const amal = await signUp('Amal Member', 'amal-146@example.com')
  await server.api.addMember({ body: { userId: amal.id, organizationId: school!.id, role: 'member' } })
  const badr = await signUp('Badr Owner', 'badr-146@example.com')
  const other = await server.api.createOrganization({ body: { name: 'Badr School', slug: 'badr-school-146' }, headers: badr.headers })
  await assignRole(other!.id, badr.id, 'administrator')
  const actor = await asas.auth.actor(asma.headers)
  assert.ok(actor)
  const options = { actor: actor as never }
  const people = asas.kayan as unknown as Record<'user' | 'organization', { operations: Record<'find' | 'findByID', (input: unknown, options: unknown) => Promise<any>> }>
  const { user, organization } = people
  const missing = async (kayan: string, id: string) => {
    await assert.rejects(() => people[kayan as 'user'].operations.findByID({ id }, options), notFound, `a ${kayan} of another tenant is not found by id`)
    const served = await asas.handler(new Request(`http://test/api/${kayan}/findByID`, {
      method: 'POST',
      headers: new Headers({ cookie: asma.headers.get('cookie')!, 'content-type': 'application/json' }),
      body: JSON.stringify({ id }),
    }))
    assert.equal(served.status, 404, 'and served, it answers 404, the same answer as a row that does not exist')
    assert.equal(((await served.json()) as { data: { key: string } }).data.key, 'error.not_found.row')
  }

  const members = await user.operations.find({ limit: 100 }, options)
  assert.deepEqual(members.docs.map((row: { name: string }) => row.name).sort(), ['Amal Member', 'Asma Owner'], 'the list holds the active organization\'s members alone')
  for (const row of members.docs) assert.deepEqual(Object.keys(row).sort(), ['id', 'name'], 'and nothing of a person but the id and the name')
  assert.equal((await user.operations.findByID({ id: amal.id }, options)).name, 'Amal Member', 'a member is read by id')
  await missing('user', badr.id)
  assert.deepEqual((await user.operations.find({ where: { name: { like: 'Badr' } } }, options)).docs, [], 'the picker\'s search finds no one of another tenant')
  assert.equal((await user.operations.find({ where: { name: { like: 'Amal' } } }, options)).docs.length, 1, 'and finds a member')
  const byEmail = await user.operations.find({ where: { email: { like: 'badr' } } }, options).catch((error: unknown) => error)
  assert.ok(byEmail instanceof AsasError && byEmail.status === 403, 'a filter on a column the title does not need is refused, so the email cannot be probed')

  const organizations = await organization.operations.find({}, options)
  assert.deepEqual(organizations.docs, [{ id: school!.id, name: 'Asma School' }], 'the active organization alone, by its id and its name')
  await missing('organization', other!.id)
  assert.deepEqual((await organization.operations.find({ where: { name: { like: 'Badr' } } }, options)).docs, [], 'and the picker\'s search finds no other')

  const served = await asas.handler(new Request('http://test/api/user/find', {
    method: 'POST',
    headers: new Headers({ cookie: asma.headers.get('cookie')!, 'content-type': 'application/json' }),
    body: JSON.stringify({ where: { name: { like: 'Owner' } } }),
  }))
  assert.equal(served.status, 200)
  assert.deepEqual((await served.json()).docs.map((row: { name: string }) => row.name), ['Asma Owner'], 'served, it answers this tenant\'s own row and not the other owner')
  const report = await (await asas.handler(new Request('http://test/api/access', { headers: asma.headers }))).json()
  assert.deepEqual(Object.keys(report.collections.user.fields).sort(), ['id', 'name'], 'the access report reads the id and the name of a person and no other column')

  // The same person as platform staff: the platform app reads every person, every column
  // included, and the tenant app still reads the members' names alone.
  await db.execute(`update "user" set role = 'super_admin' where id = '${asma.id}'`)
  const staff = await asPlatform(async () => asas.auth.actor(await onPlatform(asma.headers)))
  const everyone = await asPlatform(() => user.operations.find({ where: { id: { in: [amal.id, badr.id] } } }, { actor: staff as never }))
  assert.deepEqual(everyone.docs.map((row: { email: string }) => row.email).sort(), ['amal-146@example.com', 'badr-146@example.com'], 'the platform app reads people of every organization, email included')
  const inTenant = await user.operations.find({ limit: 100 }, { actor: (await asas.auth.actor(asma.headers)) as never })
  for (const row of inTenant.docs) assert.deepEqual(Object.keys(row).sort(), ['id', 'name'], 'while the tenant app reads the same person\'s members by id and name alone')
})

const twoTenants = async (slug: string) => {
  const made: { organization: string; owner: Awaited<ReturnType<typeof signedUp>>; course: string; tag: string; session: string }[] = []
  for (const side of ['a', 'b']) {
    const owner = await signedUp(`owner-${slug}-${side}`)
    const organization = await server.api.createOrganization({ body: { name: `Tenant ${slug} ${side}`, slug: `tenant-${slug}-${side}` }, headers: owner.headers })
    const actor = { actor: (await asas.auth.actor(owner.headers)) as never }
    const course = await courses.operations.create({ title: `Course ${slug} ${side}`, fee: 5 }, actor)
    const tag = await asas.kayan.tags.operations.create({ name: { en: `Tag ${slug} ${side}`, ar: `وسم ${side}` } }, actor)
    const session = await sessions.operations.create({ course: course.id as string, startsAt: new Date() }, actor)
    made.push({ organization: organization!.id, owner, course: course.id as string, tag: tag.id as string, session: session.id as string })
  }
  return made
}

const staffOn = async (slug: string, role: string) => {
  const person = await signedUp(slug)
  await db.execute(`update "user" set role = '${role}' where id = '${person.id}'`)
  return { ...person, actor: await asPlatform(async () => asas.auth.actor(await onPlatform(person.headers))) }
}

test('151a. on the platform every tenant kayan is read across every organization by the keys a platform role holds, and every write to one is refused by the server, a super admin\'s included', async () => {
  const [a, b] = await twoTenants('151a')
  const tenants = [a!.organization, b!.organization]
  const administrator = await staffOn('platform-151a', 'super_admin')
  const support = await staffOn('support-151a', 'support')
  const explorer = await staffOn('explorer-151a', 'explorer')
  const find = (kayan: string, options: Record<string, unknown>) =>
    (asas.kayan as unknown as Record<string, { operations: { find(input: unknown, options: unknown): Promise<{ docs: Record<string, unknown>[] }> } }>)[kayan]!.operations.find({ where: { organization: { in: tenants } }, limit: 0 }, options)
  // Across every organization with `tenant: 'all'`, which the runner grants platform staff in the platform app alone.
  const read = (kayan: string, actor: unknown) => asPlatform(() => find(kayan, { actor, tenant: 'all' }))
  // A tenant's administrator holds `'*'` and is no platform staff, in either app.
  const owner = await asas.auth.actor(a!.owner.headers)
  for (const [where, call] of [
    ['without tenant: \'all\'', () => asPlatform(() => find('courses', { actor: administrator.actor }))],
    ['outside the platform app', () => find('courses', { actor: administrator.actor, tenant: 'all' })],
    ['by a tenant\'s administrator in the tenant app', () => find('courses', { actor: owner, tenant: 'all' })],
    ['by a tenant\'s administrator in the platform app', () => asPlatform(async () => find('courses', { actor: await asas.auth.actor(await onPlatform(a!.owner.headers)), tenant: 'all' }))],
  ] as const) {
    const refused = await call().catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `a read across organizations ${where} is refused, reaching none: ${String(refused)}`)
  }
  for (const [who, staff] of [['super_admin', administrator], ['support', support], ['explorer', explorer]] as const) {
    for (const kayan of ['courses', 'sessions', 'tags']) {
      const found = await read(kayan, staff.actor)
      assert.deepEqual([...new Set(found.docs.map((row) => row.organization))].sort(), [...tenants].sort(), `${who} reads ${kayan} of both organizations`)
    }
    const course = (await read('courses', staff.actor)).docs.find((row) => row.id === a!.course)!
    assert.equal(course.title, 'Course 151a a', `${who} reads a course's columns by its keys`)
  }
  for (const staff of [administrator, explorer]) {
    await read('roles', staff.actor)
    assert.deepEqual([...new Set((await read('memberRoles', staff.actor)).docs.map((row) => row.organization))].sort(), [...tenants].sort(), 'the assignments of both organizations are read too')
  }
  for (const kayan of ['roles', 'memberRoles']) {
    const refused = await read(kayan, support.actor).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403 && refused.key === 'error.forbidden.permission', `support is refused ${kayan}`)
  }
  const report = (await (await asPlatform(async () => asas.handler(new Request('http://test/api/access', { headers: await onPlatform(support.headers) })))).json()) as AccessReport
  assert.equal(report.collections?.courses?.read, true, 'the report lists the courses for support')
  assert.equal(report.collections?.roles?.read ?? false, false, 'and not the roles')

  const as = { actor: administrator.actor as never }
  const writes: [string, string, Record<string, unknown>][] = [
    ['courses', 'create', { title: 'Platform course', fee: 1 }],
    ['courses', 'update', { id: a!.course, title: 'Renamed' }],
    ['courses', 'archive', { id: a!.course, reason: 'no' }],
    ['courses', 'delete', { id: a!.course }],
    ['courses', 'updateMany', { where: { id: { in: [a!.course] } }, data: { fee: 9 } }],
    ['courses', 'deleteMany', { where: { id: { in: [a!.course] } } }],
    ['sessions', 'create', { course: a!.course, startsAt: new Date() }],
    ['sessions', 'update', { id: a!.session, capacity: 3 }],
    ['sessions', 'archiveMany', { where: { id: { in: [a!.session] } } }],
    ['sessions', 'delete', { id: a!.session }],
    ['tags', 'create', { name: { en: 'Platform tag', ar: 'وسم' } }],
    ['tags', 'update', { id: a!.tag, name: { en: 'Renamed', ar: 'وسم' } }],
    ['tags', 'delete', { id: a!.tag }],
    ['enrollments', 'create', { session: a!.session, student: a!.owner.id }],
    ['roles', 'create', { name: 'platform-role-151a', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.find', 'courses.fields.title'] }],
    ['memberRoles', 'create', { role: 'registrar', user: a!.owner.id }],
  ]
  for (const [kayan, operation, input] of writes) {
    const refused = await asPlatform(() => (asas.kayan as unknown as Record<string, { operations: Record<string, (input: unknown, options: unknown) => Promise<unknown>> }>)[kayan]!.operations[operation]!(input, as)).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `${kayan}.${operation} is refused on the platform: ${String(refused)}`)
  }
  const assignment = (await read('memberRoles', administrator.actor)).docs.find((row) => row.organization === a!.organization)!
  for (const [operation, input] of [['update', { id: assignment.id, role: 'registrar' }], ['delete', { id: assignment.id }]] as const) {
    const refused = await asPlatform(() => (asas.kayan.memberRoles.operations[operation] as (input: unknown, options: unknown) => Promise<unknown>)(input, as)).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `memberRoles.${operation} is refused on the platform`)
  }
  const settingsWrite = await asPlatform(() => asas.global.settings.operations.update({ siteTitle: 'Platform' } as never, as)).catch((thrown: unknown) => thrown)
  assert.ok(settingsWrite instanceof AsasError && settingsWrite.status === 403, 'and so is the settings global')
  const served = await asPlatform(async () => asas.handler(new Request('http://test/api/courses/update', {
    method: 'POST',
    headers: new Headers([...(await onPlatform(administrator.headers)), ['content-type', 'application/json']]),
    body: JSON.stringify({ id: a!.course, title: 'Served' }),
  })))
  assert.equal(served.status, 403, 'a served write from the platform app is refused')
  assert.equal((await courses.operations.findByID({ id: a!.course }, { actor: (await asas.auth.actor(a!.owner.headers)) as never }))?.title, 'Course 151a a', 'and the row is as its tenant wrote it')

  await db.execute(`update "user" set role = 'none-151a' where id = '${support.id}'`)
  const none = await asPlatform(async () => asas.auth.actor(await onPlatform(support.headers)))
  const nothing = await read('courses', none).catch((thrown: unknown) => thrown)
  assert.ok(nothing instanceof AsasError && nothing.status === 403, 'a person with no platform role reads nothing on the platform')
})

test('151b. on the platform the people, the organizations and their members are read across every organization, each column by its key, and in the tenant app nothing of it reaches a member', async () => {
  const [a, b] = await twoTenants('151b')
  const support = await staffOn('support-151b', 'support')
  const kayan = asas.kayan as unknown as Record<'user' | 'organization' | 'member', { operations: Record<string, (input: unknown, options: unknown) => Promise<any>> }>
  const onPlatformRead = (name: 'user' | 'organization' | 'member', input: unknown, actor: unknown) => asPlatform(() => kayan[name].operations.find!(input, { actor }))

  const people = await onPlatformRead('user', { where: { id: { in: [a!.owner.id, b!.owner.id] } }, sort: 'email' }, support.actor)
  assert.deepEqual(people.docs.map((row: { email: string }) => row.email), ['owner-151b-a@example.com', 'owner-151b-b@example.com'], 'support reads people of both organizations, by email')
  assert.ok(['role', 'banned', 'createdAt'].every((column) => column in people.docs[0]), 'and the columns its keys name')
  const organizations = await onPlatformRead('organization', { where: { slug: { in: ['tenant-151b-a', 'tenant-151b-b'] } }, sort: 'slug' }, support.actor)
  assert.deepEqual(organizations.docs.map((row: { slug: string }) => row.slug), ['tenant-151b-a', 'tenant-151b-b'], 'and both organizations, by slug')
  const members = await onPlatformRead('member', { where: { organizationId: { equals: a!.organization } } }, support.actor)
  assert.deepEqual(members.docs.map((row: { userId: string }) => row.userId), [a!.owner.id], 'and one organization\'s members')

  const administrator = await staffOn('platform-151b', 'super_admin')
  for (const [name, operation, input] of [
    ['organization', 'update', { id: a!.organization, name: 'Renamed' }],
    ['user', 'update', { id: a!.owner.id, name: 'Renamed' }],
    ['member', 'delete', { id: members.docs[0].id }],
  ] as const) {
    const refused = await asPlatform(() => kayan[name].operations[operation]!(input, { actor: administrator.actor })).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `a managed ${name}.${operation} is refused on the platform`)
  }

  const none = await staffOn('none-151b', 'none-151b')
  for (const name of ['user', 'organization', 'member'] as const) {
    const refused = await onPlatformRead(name, {}, none.actor).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `no platform role, no ${name}`)
  }

  // In the tenant app the same support person is its membership alone: no
  // member row, and a person's id and name, whatever its platform role holds.
  await server.api.addMember({ body: { userId: support.id, organizationId: a!.organization, role: 'member' } })
  await server.api.setActiveOrganization({ body: { organizationId: a!.organization }, headers: support.headers })
  await assignRole(a!.organization, support.id, 'administrator')
  const inside = { actor: (await asas.auth.actor(support.headers)) as never }
  for (const row of (await kayan.user.operations.find!({}, inside)).docs) assert.deepEqual(Object.keys(row).sort(), ['id', 'name'], 'the tenant app reads a person\'s id and name alone')
  assert.deepEqual((await kayan.organization.operations.find!({}, inside)).docs, [{ id: a!.organization, name: 'Tenant 151b a' }], 'and its own organization, by id and name')
  const tenantMembers = await kayan.member.operations.find!({}, inside).catch((thrown: unknown) => thrown)
  assert.ok(tenantMembers instanceof AsasError && tenantMembers.status === 403, 'and no member row')
})

test('151c. the platform renames an organization and its slug through its own route, for a role holding organization.rename, audited once it succeeds and refused without the key, in the tenant app, or over a bad or taken slug', async (t) => {
  const lines: Record<string, unknown>[] = []
  t.mock.method(console, 'log', (line: unknown) => {
    if (typeof line === 'string' && line.startsWith('{"audit":"platform"')) lines.push(JSON.parse(line))
  })
  const [a, b] = await twoTenants('151c')
  const administrator = await staffOn('platform-151c', 'super_admin')
  const support = await staffOn('support-151c', 'support')
  const rename = async (headers: Headers, body: unknown, platform = true) => {
    const request = async () => asas.handler(new Request('http://test/api/platform/organizations/update', {
      method: 'POST',
      headers: new Headers([...(platform ? await onPlatform(headers) : headers), ['content-type', 'application/json']]),
      body: JSON.stringify(body),
    }))
    const response = await (platform ? asPlatform(request) : request())
    return { status: response.status, body: (await response.json()) as Record<string, any> }
  }
  const stored = async () => (await db.execute(`select name, slug from "organization" where id = '${a!.organization}'`)).rows[0]

  assert.ok(platformRoles.super_admin.permissions === '*' && !(platformRoles.support.permissions as readonly string[]).includes('organization.rename') && !(platformRoles.explorer.permissions as readonly string[]).includes('organization.rename'), 'only a super admin holds organization.rename')
  assert.ok(asas.catalog.includes('organization.rename'), 'which is a key of the catalog')
  const refused = await rename(support.headers, { id: a!.organization, name: 'By support', slug: 'by-support' })
  assert.equal(refused.status, 403, 'support holds no organization.rename')
  assert.equal(refused.body.data.key, 'error.forbidden.permission')
  const inTenant = await rename(administrator.headers, { id: a!.organization, name: 'In tenant', slug: 'in-tenant' }, false)
  assert.equal(inTenant.status, 403, 'the tenant app refuses it to a super admin, whose platform role answers nothing there')
  for (const [body, status] of [
    [{ id: a!.organization, name: 'Bad', slug: 'Not A Slug' }, 400],
    [{ id: a!.organization, name: '  ', slug: 'blank-name' }, 400],
    [{ id: a!.organization, name: 'Missing' }, 400],
    [{ id: 'no-such-organization', name: 'None', slug: 'none-151c' }, 404],
    [{ id: a!.organization, name: 'Taken', slug: 'tenant-151c-b' }, 409],
    [{ id: a!.organization, name: 'x'.repeat(256), slug: 'long-name' }, 400],
    [{ id: a!.organization, name: 'Long slug', slug: 'a'.repeat(256) }, 400],
  ] as const) {
    assert.equal((await rename(administrator.headers, body)).status, status, `${JSON.stringify(body)} answers ${status}`)
  }
  assert.deepEqual(await stored(), { name: 'Tenant 151c a', slug: 'tenant-151c-a' }, 'and nothing was written')
  assert.deepEqual(lines, [], 'and no refused call wrote a line')

  const renamed = await rename(administrator.headers, { id: a!.organization, name: 'Renamed 151c', slug: 'renamed-151c' })
  assert.equal(renamed.status, 200)
  assert.deepEqual(renamed.body, { id: a!.organization, name: 'Renamed 151c', slug: 'renamed-151c' })
  assert.deepEqual(await stored(), { name: 'Renamed 151c', slug: 'renamed-151c' }, 'the organization is renamed')
  assert.equal(lines.length, 1, 'with one audit line')
  assert.deepEqual(Object.assign({}, lines[0], { at: undefined }), { audit: 'platform', action: '/platform/organizations/update', actor: administrator.id, impersonatedBy: null, target: a!.organization, at: undefined })
  assert.ok(b, 'the other organization is untouched')
})

test('151d. the platform\'s people, organizations and members lists read their URL the way the host does, and a search, a filter, a sort and a page each narrow the read support makes there', async () => {
  const { QueryRefused, findOf, readQuery, rulesOf, writeQuery } = await import('../../../packages/mithaq-admin/registry/list-query.ts')
  const platform = asas.targets.platform.client
  const nodeIn = (value: unknown): Parameters<typeof rulesOf>[0]['node'] => {
    if (!value || typeof value !== 'object') return undefined
    const list = (value as { list?: unknown }).list
    if (list && typeof list === 'object' && 'columns' in list) return list as never
    for (const one of Object.values(value)) {
      const found = nodeIn(one)
      if (found) return found
    }
    return undefined
  }
  const support = await staffOn('support-151d', 'support')
  const listed = async (name: 'user' | 'organization' | 'member', search: string) => {
    const kayan = platform.kayan[name]!
    const node = nodeIn(kayan.pages.list)
    const related = Object.values(platform.kayan).filter((one) => kayan.fields.some((field) => field.relationTo === one.name))
    const input = findOf({
      kayan,
      query: readQuery(new URLSearchParams(search), rulesOf({ kayan, node, maxLimit: platform.maxLimit, context: { client: related, locales: ['ar', 'en'] } })),
      node,
      locales: ['ar', 'en'],
    })
    return asPlatform(() => (asas.kayan as unknown as Record<string, { operations: { find(input: unknown, options: unknown): Promise<{ docs: Record<string, any>[]; totalDocs: number; hasNextPage: boolean }> } }>)[name]!.operations.find(input, { actor: support.actor }))
  }

  const people: string[] = []
  for (let at = 0; at < 12; at++) people.push((await signedUp(`people-151d-${String(at).padStart(2, '0')}`)).id)
  await db.execute(`update "user" set banned = true where id = '${people[3]}'`)
  const first = await listed('user', 'search=people-151d&sort=email')
  assert.equal(first.totalDocs, 12, 'a search reads the people it matches, by name or email')
  assert.deepEqual(first.docs.map((row) => row.email), people.slice(0, 10).map((_, at) => `people-151d-${String(at).padStart(2, '0')}@example.com`), 'the first page, ten of them, by email')
  assert.ok(first.hasNextPage)
  const second = await listed('user', 'search=people-151d&sort=email&page=2')
  assert.deepEqual(second.docs.map((row) => row.email), ['people-151d-10@example.com', 'people-151d-11@example.com'], 'the second page, the rest')
  assert.equal((await listed('user', 'search=people-151d&sort=-email&limit=25')).docs[0]!.email, 'people-151d-11@example.com', 'sorted the other way, the last comes first')
  const banned = await listed('user', `search=people-151d&${new URLSearchParams(writeQuery({ where: { or: [{ and: [{ banned: { equals: true } }] }] } }))}`)
  assert.deepEqual(banned.docs.map((row) => row.id), [people[3]], 'a filter on the ban reads the banned person alone')

  const [a] = await twoTenants('151d')
  const organizations = await listed('organization', 'search=tenant-151d&sort=-slug')
  assert.deepEqual(organizations.docs.map((row) => row.slug), ['tenant-151d-b', 'tenant-151d-a'], 'the organizations search by slug and sort by it')
  assert.deepEqual((await listed('organization', 'where[slug][equals]=tenant-151d-a')).docs.map((row) => row.name), ['Tenant 151d a'], 'and filter by it')
  // The link an organization's Members button writes.
  const members = await listed('member', new URLSearchParams(writeQuery({ where: { or: [{ and: [{ organizationId: { equals: a!.organization } }] }] } })).toString())
  assert.deepEqual(members.docs.map((row) => row.userId), [a!.owner.id], 'the members list reads one organization\'s members')

  for (const [name, search] of [['organization', 'where[metadata][equals]=x'], ['user', 'sort=password'], ['user', 'where[__proto__][x]=1']] as const) {
    await assert.rejects(listed(name, search), (thrown: Error) => thrown instanceof QueryRefused, `${name} refuses ${search}`)
  }
})

test('176. an enrollment\'s student is a member of the tenant\'s own organization: another tenant\'s user is refused on a create, an update, an updateMany and served over HTTP, and the tenant\'s own member is admitted', async () => {
  const signUp = async (name: string, email: string) => {
    const made = await server.api.signUpEmail({ body: { name, email, password: 'a-long-enough-password' }, returnHeaders: true })
    return { id: made.response.user.id as string, headers: new Headers({ cookie: made.headers.get('set-cookie') ?? '' }) }
  }
  const owner = await signUp('Hind Owner', 'hind-149@example.com')
  const school = await server.api.createOrganization({ body: { name: 'Hind School', slug: 'hind-school-149' }, headers: owner.headers })
  await assignRole(school!.id, owner.id, 'administrator')
  const member = await memberOf(school!.id, 'Huda Member', 'huda-149@example.com')
  const stranger = await signUp('Zaid Owner', 'zaid-149@example.com')
  await server.api.createOrganization({ body: { name: 'Zaid School', slug: 'zaid-school-149' }, headers: stranger.headers })
  const actor = await asas.auth.actor(owner.headers)
  assert.ok(actor)
  const options = { actor }
  const course = await courses.operations.create({ title: 'Enrolled across tenants' }, options)
  const session = await sessions.operations.create({ course: course.id, startsAt: new Date('2027-05-01T09:00:00.000Z'), capacity: 4 }, options)
  const refused = async (write: Promise<unknown>, message: string) => {
    const thrown = await write.catch((error: unknown) => error)
    assert.ok(thrown instanceof AsasError && thrown.status === 400, message)
    assert.equal(thrown.key, 'error.invalid.reference', `${message}, under the reference key`)
    assert.deepEqual(thrown.params, { kayan: 'enrollments', field: 'student', target: 'user' }, `${message}, naming the field and the target`)
  }

  await refused(enrollments.operations.create({ session: session.id, student: stranger.id }, options), 'another tenant\'s user is refused as the student of a create')
  const made = await enrollments.operations.create({ session: session.id, student: member }, options)
  assert.equal(made.student, member, 'the tenant\'s own member is admitted')
  // Postgres answers a uuid in lowercase, so a session named in uppercase is
  // still the row that is there.
  const shouted = await enrollments.operations.create({ session: session.id.toUpperCase(), student: member }, options)
  assert.equal(shouted.session, session.id, 'a uuid named in uppercase is admitted and stored as the row it names')
  assert.equal((await enrollments.operations.create({ session: session.id, student: owner.id }, options)).student, owner.id, 'and so is the owner, who is a member too')
  await refused(enrollments.operations.update({ id: made.id, student: stranger.id }, options), 'an update to another tenant\'s user is refused')
  await refused(
    enrollments.operations.updateMany({ where: { id: { equals: made.id } }, data: { student: stranger.id } }, options),
    'and so is an updateMany',
  )
  assert.equal((await enrollments.operations.findByID({ id: made.id }, options))?.student, member, 'the row still names the member')
  assert.equal((await enrollments.operations.update({ id: made.id, student: owner.id }, options)).student, owner.id, 'an update to the tenant\'s own member is admitted')

  const served = await asas.handler(new Request('http://test/api/enrollments/create', {
    method: 'POST',
    headers: new Headers({ cookie: owner.headers.get('cookie')!, 'content-type': 'application/json' }),
    body: JSON.stringify({ session: session.id, student: stranger.id }),
  }))
  assert.equal(served.status, 400, 'served, the create naming another tenant\'s user is a 400')
  assert.equal((await served.json()).data.key, 'error.invalid.reference', 'under the same key')
})

