test('178. reverses #158 for localUsers: unset, LOCAL_AUTH_SECRET leaves every operation and every generated file as it is set, and every POST of local auth refuses naming the variable and signs nothing', async () => {
  // One build per process, since the template reads the variable as it loads.
  // The child prints what the generators write from, every screen's
  // projection and every scope's copy, beside the strategies and operations,
  // and, unset, what each local auth path answers.
  const built = (secret: string | undefined) => new Promise<{ code: number; stdout: string; stderr: string }>((resolve) => {
    const { LOCAL_AUTH_SECRET: _secret, ...rest } = process.env
    const script = `
      const { asas } = await import('./asas.ts')
      const answers = {}
      if (!process.env.LOCAL_AUTH_SECRET) {
        for (const path of ['first-register', 'login', 'refresh-token', 'logout', 'forgot-password', 'reset-password', 'unlock', 'verify/a-token']) {
          const answer = await asas.handler(new Request('http://test/api/auth/local/' + path, { method: 'POST', body: JSON.stringify({ email: 'nosecret-178@example.com', password: 'a-long-enough-password', token: 'a-token' }) }))
          answers[path] = { status: answer.status, body: await answer.json() }
        }
        // A real token, HMAC'd under an empty key, which is what anyone could
        // sign with if an empty secret were ever a key.
        const { createHmac } = await import('node:crypto')
        const part = (value) => Buffer.from(JSON.stringify(value)).toString('base64url')
        const signed = part({ alg: 'HS256', typ: 'JWT' }) + '.' + part({ collection: 'localUsers', id: 'anyone', sid: 'any', exp: Math.floor(Date.now() / 1000) + 3600 })
        const forged = signed + '.' + createHmac('sha256', '').update(signed).digest('base64url')
        for (const [name, headers] of [['me.bearer', { authorization: 'Bearer ' + forged }], ['me.cookie', { cookie: 'local-token=' + forged }]]) {
          const answer = await asas.handler(new Request('http://test/api/auth/local/me', { headers }))
          answers[name] = { status: answer.status, body: await answer.json() }
        }
        // The public sign-up, the kayan's own create, is refused too.
        const signUp = await asas.handler(new Request('http://test/api/localUsers/create', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email: 'nosecret-178@example.com', password: 'a-long-enough-password' }) }))
        answers.create = { status: signUp.status, body: await signUp.json() }
      }
      console.log(JSON.stringify({
        strategies: asas.auth.strategies.map((one) => one.name),
        operations: Object.keys(asas.kayan.localUsers.operations),
        screens: Object.fromEntries(['dashboard', 'portal', 'platform'].map((name) => [name, asas.targets[name].client])),
        messages: asas.messages,
        answers,
      }))
      await asas.destroy()`
    execFile(
      process.execPath,
      ['--input-type=module', '-e', script],
      { cwd: fileURLToPath(new URL('.', import.meta.url)), env: { ...rest, ...(secret ? { LOCAL_AUTH_SECRET: secret } : {}) } as NodeJS.ProcessEnv, maxBuffer: 64 * 1024 * 1024 },
      (error: unknown, stdout: string, stderr: string) => resolve({ code: error && typeof error === 'object' && 'code' in error ? Number(error.code) : 0, stdout, stderr }),
    )
  })
  type Built = { strategies: string[]; operations: string[]; screens: unknown; messages: unknown; answers: Record<string, { status: number; body?: { message?: string } }> }
  const [unset, set] = await Promise.all([built(undefined), built('a-secret-from-the-environment-of-32-characters')])
  assert.equal(unset.code, 0, unset.stderr)
  assert.equal(set.code, 0, set.stderr)
  const without = JSON.parse(unset.stdout) as Built
  const withSecret = JSON.parse(set.stdout) as Built
  assert.deepEqual(without.strategies, ['user', 'local'], 'the local strategy is built either way')
  assert.deepEqual(withSecret.strategies, ['user', 'local'])
  assert.ok(without.operations.includes('create') && without.operations.includes('update'), 'and the kayan keeps its operations')
  assert.deepEqual(without.operations, withSecret.operations)
  assert.deepEqual(without.screens, withSecret.screens, 'so every screen.json is the same')
  assert.deepEqual(without.messages, withSecret.messages, 'and so is every copy file')
  assert.match(unset.stderr, /LOCAL_AUTH_SECRET/, 'and the build says once why local auth is off')

  for (const [path, answer] of Object.entries(without.answers)) {
    if (path.startsWith('me.') || path === 'create') continue
    assert.equal(answer.status, 503, `${path} is refused`)
    assert.match(answer.body?.message ?? '', /LOCAL_AUTH_SECRET is not set/, `and ${path} names the variable`)
  }
  // `/me` answers 200 for nobody, so the user it names is what is asserted.
  assert.deepEqual(without.answers['me.bearer'], { status: 200, body: { user: null } }, 'no bearer token signed under an empty key authenticates anyone')
  assert.deepEqual(without.answers['me.cookie'], { status: 200, body: { user: null } }, 'and no such cookie does')
  const signUp = without.answers.create as { status: number; body?: { message?: string; data?: { key?: string } } }
  assert.equal(signUp.status, 403, 'a public sign-up is refused')
  assert.match(signUp.body?.message ?? '', /LOCAL_AUTH_SECRET is not set/, 'in the same words, naming the variable')
  assert.equal(signUp.body?.data?.key, 'error.forbidden.local_auth_off')
  const { rows } = (await db.execute(`select count(*)::int as n from local_users where email = 'nosecret-178@example.com'`)) as { rows: { n: number }[] }
  assert.equal(rows[0]!.n, 0, 'and nothing was written, by any path')
})

test('179. a role name is one row per tenant and an assignment one row per member and role, each a 409 on the second write, while another tenant keeps its own of the same name', async () => {
  const owner = await signedUp('owner-158')
  const organization = await server.api.createOrganization({ body: { name: 'Unique org 158', slug: 'unique-org-158' }, headers: owner.headers })
  const other = await signedUp('other-158')
  const otherOrganization = await server.api.createOrganization({ body: { name: 'Other org 158', slug: 'other-org-158' }, headers: other.headers })
  const actor = await asas.auth.actor(owner.headers)
  const otherActor = await asas.auth.actor(other.headers)
  assert.ok(actor && otherActor)

  await asas.kayan.roles.operations.create({ name: 'curator', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: actor as never })
  const twice = await asas.kayan.roles.operations
    .create({ name: 'curator', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.update', 'courses.fields.title'] }, { actor: actor as never })
    .then(() => undefined, (error: { status?: number; key?: string }) => error)
  assert.equal(twice?.status, 409, 'a second role of one name in one tenant is a conflict, so no two rows union their keys')
  assert.equal(twice?.key, 'error.conflict.unique')
  const renamed = await asas.kayan.roles.operations.create({ name: 'curator-2', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: actor as never })
  const onto = await asas.kayan.roles.operations
    .update({ id: renamed.id, name: 'curator' }, { actor: actor as never })
    .then(() => undefined, (error: { status?: number }) => error)
  assert.equal(onto?.status, 409, 'and so is renaming one onto a name its tenant already holds')
  const elsewhere = await asas.kayan.roles.operations.create({ name: 'curator', label: { en: 'Test role', ar: 'دور تجريبي' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: otherActor as never })
  assert.equal(elsewhere.name, 'curator', 'another tenant holds its own role of the same name')

  const member = await memberOf(organization!.id, 'Member 158', 'member-158@example.com')
  await asas.kayan.memberRoles.operations.create({ role: 'curator', user: member }, { actor: actor as never })
  const again = await asas.kayan.memberRoles.operations
    .create({ role: 'curator', user: member }, { actor: actor as never })
    .then(() => undefined, (error: { status?: number; key?: string }) => error)
  assert.equal(again?.status, 409, 'one member holds one role once')
  assert.equal(again?.key, 'error.conflict.unique')
  assert.ok(otherOrganization)
})

