/**
 * The organization's owner is Better Auth's own creator role, which the provider already
 * keeps: nobody but an owner removes or demotes one, and the last one never leaves. So the
 * owner always holds `administrator` in its tenant, whatever the assignments say, and its
 * row is not removed from the page where the removal would change nothing.
 */
test('166a. the organization\'s owner always holds administrator: another administrator is refused removing their row, alone or in bulk, the row gone by SQL takes no key, and Better Auth\'s own owner rules still stand', async () => {
  const owner = await signedUp('owner-166a')
  const organization = await server.api.createOrganization({ body: { name: 'Owner 166', slug: 'owner-166' }, headers: owner.headers })
  const tenant = organization!.id
  const row = (await db.execute(`select id from member_roles where organization_id = '${tenant}' and user_id = '${owner.id}' and role = 'administrator'`)).rows[0] as { id: string }
  assert.ok(row, 'the creation hook assigned the owner administrator')
  const second = await joined(tenant, 'second-166a', 'administrator')
  for (const [what, write] of [
    ['a delete', () => asas.kayan.memberRoles.operations.delete({ id: row.id }, { actor: second.actor as never })],
    ['a change of role', () => asas.kayan.memberRoles.operations.update({ id: row.id, role: 'registrar' }, { actor: second.actor as never })],
    ['a bulk delete', () => asas.kayan.memberRoles.operations.deleteMany({ where: { user: { equals: owner.id } } }, { actor: second.actor as never })],
  ] as const) {
    const refused = await write().catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError, `${what} of the owner's administrator is a refusal the caller caused: ${String(refused)}`)
    assert.equal(refused.status, 403, `${what} is 403`)
    assert.equal(refused.key, 'error.forbidden.owner_role', `${what} is refused under its own key`)
  }
  assert.deepEqual((await db.execute(`select role from member_roles where id = '${row.id}'`)).rows, [{ role: 'administrator' }], 'and the row is unchanged')

  await db.execute(`delete from member_roles where id = '${row.id}'`)
  const actor = await asas.auth.actor(owner.headers)
  assert.deepEqual(assignedRoles(actor as never), ['administrator'], 'the reader answers administrator for the owner')
  assert.equal(actorPermissions(actor), true, 'so the owner still holds every key')
  assert.ok(Array.isArray((await courses.operations.find({}, { actor: actor as never })).docs), 'and reads the tenant')

  const left = await server.api.leaveOrganization({ body: { organizationId: tenant }, headers: owner.headers }).catch((thrown: unknown) => thrown)
  assert.match(String((left as Error).message), /only owner/, 'the only owner does not leave')
  const removed = await server.api.removeMember({ body: { memberIdOrEmail: 'owner-166a@example.com', organizationId: tenant }, headers: second.headers }).catch((thrown: unknown) => thrown)
  assert.ok(removed instanceof Error, 'and a member who is no owner does not remove one')
  assert.deepEqual((await db.execute(`select role from member where organization_id = '${tenant}' and user_id = '${owner.id}'`)).rows, [{ role: 'owner' }])

  // A spaced owner name is no owner to the guard either, as the provider
  // matches it: that row comes off like any other administrator's.
  await db.execute(`update member set role = 'member, owner' where organization_id = '${tenant}' and user_id = '${owner.id}'`)
  await assignRole(tenant, owner.id, 'administrator')
  const spaced = (await db.execute(`select id from member_roles where organization_id = '${tenant}' and user_id = '${owner.id}'`)).rows[0] as { id: string }
  await asas.kayan.memberRoles.operations.delete({ id: spaced.id }, { actor: second.actor as never })
  assert.deepEqual((await db.execute(`select id from member_roles where id = '${spaced.id}'`)).rows, [], 'the guard reads "member, owner" as no owner')
  assert.deepEqual(assignedRoles((await asas.auth.actor(owner.headers)) as never), [], 'and neither does the reader')
})

/**
 * Every tenant keeps a member who may manage roles. Two administrators removing each
 * other at the same moment would each see the other still there; the check runs under a
 * lock on the tenant, so the second one to reach it sees the first one's removal.
 */
test('166b. two administrators removing each other at the same moment leave one of them, and the other removal is refused 409 because the tenant would keep nobody who manages roles', async () => {
  const creator = await signedUp('creator-166b')
  const organization = await server.api.createOrganization({ body: { name: 'Race 166', slug: 'race-166' }, headers: creator.headers })
  const tenant = organization!.id
  await db.execute(`update member set role = 'member' where organization_id = '${tenant}'`)
  await db.execute(`delete from member_roles where organization_id = '${tenant}'`)
  const first = await joined(tenant, 'first-166b', 'administrator')
  const second = await joined(tenant, 'second-166b', 'administrator')
  const rows = (await db.execute(`select id, user_id from member_roles where organization_id = '${tenant}'`)).rows as { id: string; user_id: string }[]
  const rowOf = (user: string) => rows.find((one) => one.user_id === user)!.id

  // Both rows held, so both removals are in flight in their own transactions
  // before either decides anything.
  let release!: () => void
  const released = new Promise<void>((resolve) => (release = resolve))
  let held!: () => void
  const holding = new Promise<void>((resolve) => (held = resolve))
  const holder = db.transaction(async (tx) => {
    await tx.execute(`select id from member_roles where organization_id = '${tenant}' for update`)
    held()
    await released
  })
  await holding
  const removals = [
    asas.kayan.memberRoles.operations.delete({ id: rowOf(second.id) }, { actor: first.actor as never }),
    asas.kayan.memberRoles.operations.delete({ id: rowOf(first.id) }, { actor: second.actor as never }),
  ].map((removal) => removal.then(() => 'removed' as const, (thrown: unknown) => thrown))
  try {
    for (let tries = 0; ; tries++) {
      const waiting = (await db.execute(`select count(*)::int as waiting from pg_stat_activity where datname = current_database() and wait_event_type = 'Lock' and query like '%member_roles%'`)).rows[0] as { waiting: number }
      if (waiting.waiting >= 2) break
      assert.ok(tries < 400, 'both removals reach the database')
      await setTimeout(25)
    }
  } finally {
    release()
    await holder
  }

  const outcomes = await Promise.all(removals)
  assert.equal(outcomes.filter((one) => one === 'removed').length, 1, `exactly one removal goes ahead: ${outcomes.map(String).join(', ')}`)
  const refused = outcomes.find((one) => one !== 'removed')
  assert.ok(refused instanceof AsasError, `the other is a refusal the caller caused: ${String(refused)}`)
  assert.equal(refused.status, 409)
  assert.equal(refused.key, 'error.conflict.last_manager')
  assert.deepEqual((await db.execute(`select count(*)::int as left from member_roles where organization_id = '${tenant}'`)).rows, [{ left: 1 }], 'and one administrator is left')
})

/**
 * The rule `keepsOwnManager` holds for an assignment, held for the role itself: nobody
 * edits a role they hold so it stops letting them manage roles.
 */
test('166c. a member is refused editing a role they hold so it no longer manages roles, even as the tenant\'s last manager, and another manager edits it', async () => {
  const owner = await signedUp('owner-166c')
  const organization = await server.api.createOrganization({ body: { name: 'Steward 166', slug: 'steward-166' }, headers: owner.headers })
  const tenant = organization!.id
  const ownerActor = await asas.auth.actor(owner.headers)
  const managing = asas.catalog.filter((key) => key.startsWith('roles.'))
  const role = await asas.kayan.roles.operations.create(
    { name: 'steward', label: { en: 'Steward', ar: 'وكيل' }, permissions: ['courses.find', 'courses.fields.title', ...managing] },
    { actor: ownerActor as never },
  )
  const steward = await joined(tenant, 'steward-166c', 'steward')
  const strip = (actor: unknown) => asas.kayan.roles.operations.update({ id: role.id, permissions: ['courses.find', 'courses.fields.title'] }, { actor: actor as never })

  const refused = await strip(steward.actor).catch((thrown: unknown) => thrown)
  assert.ok(refused instanceof AsasError, `stripping one's own role is a refusal the caller caused: ${String(refused)}`)
  assert.equal(refused.status, 403)
  assert.equal(refused.key, 'error.forbidden.own_role')
  const kept = ['courses.find', 'courses.fields.title', ...managing.filter((key) => key !== 'roles.delete')]
  await asas.kayan.roles.operations.update({ id: role.id, permissions: kept }, { actor: steward.actor as never })

  await db.execute(`update member set role = 'member' where organization_id = '${tenant}'`)
  await db.execute(`delete from member_roles where organization_id = '${tenant}' and role = 'administrator'`)
  const alone = await strip(await asas.auth.actor(steward.headers)).catch((thrown: unknown) => thrown)
  assert.equal((alone as AsasError).key, 'error.forbidden.own_role', 'the last manager does not strip their own role')
  assert.deepEqual((await db.execute(`select permissions from roles where id = '${role.id}'`)).rows, [{ permissions: kept }])

  await db.execute(`update member set role = 'owner' where organization_id = '${tenant}' and user_id = '${owner.id}'`)
  const stripped = await strip(await asas.auth.actor(owner.headers))
  assert.deepEqual(stripped.permissions, ['courses.find', 'courses.fields.title'], 'another manager edits it while a manager remains')
})

/**
 * The stale-name guard counts the assignments that would meet a role's name without the
 * author's read of them: a count and nothing else leaves the step, so a role's author
 * needs no `memberRoles` key.
 */
test('166d. an actor holding roles.create and no memberRoles key creates a role, and the stale-name guard still refuses a name an assignment of its tenant carries', async () => {
  const owner = await signedUp('owner-166d')
  const organization = await server.api.createOrganization({ body: { name: 'Author 166', slug: 'author-166' }, headers: owner.headers })
  const tenant = organization!.id
  const ownerActor = await asas.auth.actor(owner.headers)
  const writing = ['courses.find', 'courses.fields.title', 'roles.create', ...asas.catalog.filter((key) => key.startsWith('roles.fields.'))]
  await asas.kayan.roles.operations.create({ name: 'author', label: { en: 'Author', ar: 'مؤلف' }, permissions: writing }, { actor: ownerActor as never })
  const author = await joined(tenant, 'author-166d', 'author')
  assert.ok(![...(actorPermissions(author.actor) as ReadonlySet<string>)].some((key) => key.startsWith('memberRoles.')), 'the author holds no memberRoles key')

  const made = await asas.kayan.roles.operations.create({ name: 'scribe', label: { en: 'Scribe', ar: 'كاتب' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: author.actor as never })
  assert.equal(made.name, 'scribe', 'the author creates a role')

  await assignRole(tenant, author.id, 'phantom')
  const refused = await asas.kayan.roles.operations
    .create({ name: 'phantom', label: { en: 'Phantom', ar: 'طيف' }, permissions: ['courses.find', 'courses.fields.title'] }, { actor: author.actor as never })
    .catch((thrown: unknown) => thrown)
  assert.ok(refused instanceof AsasError && refused.status === 409, `a name an assignment carries is refused 409: ${String(refused)}`)
  assert.equal(refused.key, 'error.conflict.role_assigned')
  assert.deepEqual(refused.params, { kayan: 'roles', role: 'phantom', count: 1 }, 'naming a count and no member')
})

/**
 * The provider validates an invitation's roles trimmed and stores them as written, and its
 * own owner checks match untrimmed, so an inviter who may not invite an owner could store
 * "member, owner". The template refuses a role value with whitespace or an empty name
 * where it is written and where an invitation is accepted.
 */
test('166e. a provider role with whitespace around a name is refused where an invitation is written and where one is accepted', async () => {
  const owner = await signedUp('owner-166e')
  const organization = await server.api.createOrganization({ body: { name: 'Invite 166', slug: 'invite-166' }, headers: owner.headers })
  const tenant = organization!.id
  const inviter = await joined(tenant, 'inviter-166e', 'administrator', 'admin')
  for (const role of [['member', ' owner'], 'member, owner', 'owner ', 'member,,admin']) {
    const refused = await server.api
      .createInvitation({ body: { email: 'invitee-166e@example.com', role, organizationId: tenant }, headers: inviter.headers })
      .catch((thrown: unknown) => thrown)
    assert.equal((refused as { body?: { code?: string } }).body?.code, 'error.invalid.member_role', `${JSON.stringify(role)} is refused: ${String(refused)}`)
  }
  assert.deepEqual((await db.execute(`select id from invitation where email = 'invitee-166e@example.com'`)).rows, [], 'and no invitation was stored')

  // One stored that way, which the invitee then accepts.
  const invitee = await signedUp('invitee-166e')
  const invitation = await server.api.createInvitation({ body: { email: 'invitee-166e@example.com', role: 'member', organizationId: tenant }, headers: inviter.headers })
  await db.execute(`update invitation set role = 'member, owner' where id = '${invitation.id}'`)
  const accepted = await server.api.acceptInvitation({ body: { invitationId: invitation.id }, headers: invitee.headers }).catch((thrown: unknown) => thrown)
  assert.equal((accepted as { body?: { code?: string } }).body?.code, 'error.invalid.member_role', `the stored spacing is refused on accept: ${String(accepted)}`)
  assert.deepEqual((await db.execute(`select id from member where organization_id = '${tenant}' and user_id = '${invitee.id}'`)).rows, [], 'and the invitee joined nothing')
})

/**
 * The stale-name count is asked only of the actor's own organization: a tenant a create
 * names is checked by the store seal after the steps, so a count against it first would
 * answer another tenant's assignments.
 */
test('166f. a role created naming another tenant is refused for naming it, the same whether that tenant holds an assignment of the name or not, so it never answers that tenant\'s assignments', async () => {
  const mine = await signedUp('mine-166f')
  await server.api.createOrganization({ body: { name: 'Mine 166', slug: 'mine-166' }, headers: mine.headers })
  const actor = await asas.auth.actor(mine.headers)
  const theirs = await signedUp('theirs-166f')
  const other = await server.api.createOrganization({ body: { name: 'Theirs 166', slug: 'theirs-166' }, headers: theirs.headers })
  await assignRole(other!.id, theirs.id, 'secret-166f')
  for (const name of ['secret-166f', 'unused-166f']) {
    const refused = await asas.kayan.roles.operations
      .create({ name, label: { en: 'Probe', ar: 'مسبار' }, permissions: ['courses.find', 'courses.fields.title'], organization: other!.id } as never, { actor: actor as never })
      .catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError, `${name} is a refusal the caller caused: ${String(refused)}`)
    assert.equal(refused.status, 400, `${name} answers the field, never the other tenant's assignments`)
    assert.match(refused.message, /Unrecognized key: "organization"/)
  }
  assert.deepEqual((await db.execute(`select id from roles where name in ('secret-166f', 'unused-166f')`)).rows, [])
})

const versionsTenant = async (slug: string) => {
  const owner = await signedUp(`owner-${slug}`)
  const organization = await server.api.createOrganization({ body: { name: `Versions ${slug}`, slug: `versions-${slug}` }, headers: owner.headers })
  const actor = await asas.auth.actor(owner.headers)
  assert.ok(actor)
  const joined = async (role: string) => {
    const one = await signedUp(`${role}-${slug}`)
    await server.api.addMember({ body: { userId: one.id, organizationId: organization!.id, role: 'member' } })
    await server.api.setActiveOrganization({ body: { organizationId: organization!.id }, headers: one.headers })
    await assignRole(organization!.id, one.id, role)
    const member = await asas.auth.actor(one.headers)
    assert.ok(member)
    return { actor: member as never, headers: one.headers }
  }
  return { options: { actor: actor as never }, headers: owner.headers, joined }
}
const courseVersions = async (id: string) =>
  (await db.execute(`select id, version, latest, autosave from _courses_versions where parent_id = '${id}' order by updated_at, created_at`)).rows as { id: string; version: Record<string, unknown>; latest: boolean; autosave: boolean }[]
const courseRow = async (id: string) =>
  (await db.execute(`select title, fee, _status from courses where id = '${id}'`)).rows[0] as { title: string; fee: string | null; _status: string }

test('132a. a draft save writes a version alone and leaves the row, and a publish writes the row and a version, carrying the draft', async () => {
  const { options } = await versionsTenant('132a')
  const course = await courses.operations.create({ title: 'Draft base', fee: 10 }, options)
  assert.equal(course._status, 'published', 'a write without draft publishes')
  assert.equal((await courseVersions(course.id)).length, 1, 'and keeps a version')

  const drafted = await courses.operations.update({ id: course.id, title: 'Drafted' }, { ...options, draft: true })
  assert.equal(drafted.title, 'Drafted', 'the draft save answers with the draft')
  assert.equal(drafted._status, 'draft')
  assert.deepEqual(await courseRow(course.id), { title: 'Draft base', fee: '10', _status: 'published' }, 'the row is untouched')
  const versions = await courseVersions(course.id)
  assert.equal(versions.length, 2, 'and one more version holds the draft')
  assert.equal(versions.at(-1)!.version.title, 'Drafted')
  assert.deepEqual(versions.map((one) => one.latest), [false, true], 'the new one is the latest')
  assert.equal((await courses.operations.findByID({ id: course.id }, options))?.title, 'Draft base', 'a plain read reads the published row')
  assert.equal((await courses.operations.findByID({ id: course.id }, { ...options, draft: true }))?.title, 'Drafted', 'and a draft read the latest version')

  const published = await courses.operations.update({ id: course.id, fee: 20 }, options)
  assert.equal(published.title, 'Drafted', 'a publish carries the draft it builds on')
  assert.deepEqual(await courseRow(course.id), { title: 'Drafted', fee: '20', _status: 'published' }, 'onto the row')
  assert.equal((await courseVersions(course.id)).length, 3, 'and keeps a version of what it published')
})

test('132b. a row made as a draft is read by no plain read, and a draft read finds it', async () => {
  const { options } = await versionsTenant('132b')
  const draft = await courses.operations.create({ title: 'Never published 132b' }, { ...options, draft: true })
  assert.equal(draft._status, 'draft')
  assert.equal((await courseRow(draft.id))._status, 'draft', 'a draft create still makes the row')
  const where = { title: { equals: 'Never published 132b' } }
  assert.equal((await courses.operations.find({ where }, options)).totalDocs, 0, 'find leaves it out')
  await assert.rejects(() => courses.operations.findByID({ id: draft.id }, options), notFound, 'findByID leaves it out')
  assert.equal((await courses.operations.count({ where }, options)).totalDocs, 0, 'count leaves it out')
  const drafts = await courses.operations.find({ where }, { ...options, draft: true })
  assert.deepEqual(drafts.docs.map((one) => one.id), [draft.id], 'and a draft read finds it')
})

test('132b2. a draft made with no title, over the API and by autosave, is deleted like any other row', async () => {
  const { headers } = await versionsTenant('132b2')
  const cookie = new Headers(headers).get('cookie') ?? ''
  for (const query of ['draft=true', 'draft=true&autosave=true']) {
    const made = await apiCall(`courses/create?${query}`, {}, { cookie })
    assert.equal(made.status, 200, `a ${query} create with no title answers 200`)
    const { id } = await bodyOf(made)
    const removed = await apiCall('courses/delete', { id }, { cookie })
    assert.equal(removed.status, 200, `the ${query} draft with no title is deleted: ${JSON.stringify(await removed.clone().json())}`)
    assert.equal((await bodyOf(removed)).id, id, 'and the answer is the row it removed')
    assert.equal((await db.execute(`select id from courses where id = '${id}'`)).rows.length, 0, 'the row is gone')
  }
  // A row stored published with no title is one the server cannot read, which
  // is a fault, so the 500 it answers is in the server's log too.
  const { id } = await bodyOf(await apiCall('courses/create?draft=true', {}, { cookie }))
  await db.execute(`update courses set _status = 'published' where id = '${id}'`)
  const logged = mock.method(console, 'error', () => {})
  try {
    for (const call of [apiCall, rpcCall]) {
      const broken = await call('courses/findByID', { id }, { cookie })
      assert.equal(broken.status, 500, 'a row the output shape refuses answers 500')
    }
    assert.equal(logged.mock.callCount(), 2, 'and each 500 is logged once')
    assert.match(String(logged.mock.calls[0]!.arguments[0]), /Repair the stored row/, 'naming what broke')
  } finally {
    logged.mock.restore()
  }
  await db.execute(`delete from courses where id = '${id}'`)
})

test('132c. a draft read and every version operation need their own key', async () => {
  const { options, joined } = await versionsTenant('132c')
  const course = await courses.operations.create({ title: 'Keyed' }, options)
  const { actor } = await joined('instructor')
  assert.equal((await courses.operations.findByID({ id: course.id }, { actor }))?.title, 'Keyed', 'the instructor reads the course')
  for (const [what, attempt] of [
    ['a draft read', () => courses.operations.findByID({ id: course.id }, { actor, draft: true })],
    ['findVersions', () => courses.operations.findVersions({}, { actor })],
    ['restoreVersion', () => courses.operations.restoreVersion({ id: course.id }, { actor })],
  ] as const) {
    const refused = await attempt().catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 403, `${what} is refused 403 without its key: ${String(refused)}`)
    assert.equal(refused.key, 'error.forbidden.permission')
  }
})

test('132d. no version of a row in another tenant is read, drafted or restored', async () => {
  const mine = await versionsTenant('132d-mine')
  const theirs = await versionsTenant('132d-theirs')
  const course = await courses.operations.create({ title: 'Theirs 132d' }, theirs.options)
  await courses.operations.update({ id: course.id, title: 'Their draft 132d' }, { ...theirs.options, draft: true })
  const [version] = await courseVersions(course.id)
  assert.ok(version)
  assert.equal((await courses.operations.findVersions({ where: { parent: { equals: course.id } } }, mine.options)).totalDocs, 0, 'findVersions reads none of them')
  await assert.rejects(() => courses.operations.findVersionByID({ id: version.id }, mine.options), notFound, 'findVersionByID reads none of them')
  await assert.rejects(() => courses.operations.findByID({ id: course.id }, { ...mine.options, draft: true }), notFound, 'a draft read reads none of them')
  const restored = await courses.operations.restoreVersion({ id: version.id }, mine.options).catch((thrown: unknown) => thrown)
  assert.ok(restored instanceof AsasError && restored.status === 404, `a restore is refused as an absent version: ${String(restored)}`)
  assert.equal((await courses.operations.findVersions({ where: { parent: { equals: course.id } } }, theirs.options)).totalDocs, 2, 'while their own tenant reads both')
})

test('132e. a version is cut to the columns its reader may read', async () => {
  const { options, joined } = await versionsTenant('132e')
  const course = await courses.operations.create({ title: 'Cut', summary: 'Only the administrator reads this' }, options)
  const { actor } = await joined('registrar')
  const [seen] = (await courses.operations.findVersions({ where: { parent: { equals: course.id } } }, { actor })).docs
  assert.ok(seen)
  assert.equal(seen.version.title, 'Cut', 'the registrar reads the title it holds a key for')
  assert.ok(!('summary' in seen.version), 'and never the summary it holds none for')
  const [whole] = (await courses.operations.findVersions({ where: { parent: { equals: course.id } } }, options)).docs
  assert.equal(whole!.version.summary, 'Only the administrator reads this', 'which the administrator reads')
  assert.equal((await courses.operations.findVersionByID({ id: seen.id }, { actor }))!.version.summary, undefined, 'one version by id is cut the same way')
})

test('132f. an autosave overwrites the latest version only where that one is itself an autosave', async () => {
  const { options } = await versionsTenant('132f')
  const course = await courses.operations.create({ title: 'Autosaved' }, options)
  const autosave = { ...options, draft: true, autosave: true }
  await courses.operations.update({ id: course.id, title: 'Typing' }, autosave)
  assert.deepEqual((await courseVersions(course.id)).map((one) => one.autosave), [false, true], 'the first autosave is a version of its own')
  await courses.operations.update({ id: course.id, title: 'Typing more' }, autosave)
  const overwritten = await courseVersions(course.id)
  assert.deepEqual(overwritten.map((one) => one.autosave), [false, true], 'the next overwrites it in place')
  assert.equal(overwritten.at(-1)!.version.title, 'Typing more')
  await courses.operations.update({ id: course.id, title: 'Saved draft' }, { ...options, draft: true })
  await courses.operations.update({ id: course.id, title: 'Typing again' }, autosave)
  assert.deepEqual((await courseVersions(course.id)).map((one) => one.autosave), [false, true, false, true], 'an autosave after a draft save is a version of its own')
})

test('132g. a kayan keeps its last max versions', async () => {
  const memo = await memoAsas.kayan.memos.operations.create({ body: 'one' })
  for (const body of ['two', 'three', 'four']) await memoAsas.kayan.memos.operations.update({ id: memo.id, body })
  const kept = (await db.execute(`select version from _memos_versions where parent_id = '${memo.id}' order by updated_at`)).rows as { version: { body: string } }[]
  assert.deepEqual(kept.map((one) => one.version.body), ['three', 'four'], 'the two newest stay and the rest are deleted')
})

test('132h. a restore writes a version onto the row and appends one, or appends a draft alone', async () => {
  const { options } = await versionsTenant('132h')
  const course = await courses.operations.create({ title: 'First title', fee: 5 }, options)
  await courses.operations.update({ id: course.id, title: 'Second title', fee: 6 }, options)
  const [first] = await courseVersions(course.id)
  const restored = await courses.operations.restoreVersion({ id: first!.id }, options)
  assert.equal(restored.title, 'First title')
  assert.deepEqual(await courseRow(course.id), { title: 'First title', fee: '5', _status: 'published' }, 'the row holds the version')
  const after = await courseVersions(course.id)
  assert.equal(after.length, 3, 'and a version of the restore is appended')
  assert.equal(after.at(-1)!.version.title, 'First title')

  const [, second] = after
  await courses.operations.restoreVersion({ id: second!.id }, { ...options, draft: true })
  assert.equal((await courseRow(course.id)).title, 'First title', 'a draft restore leaves the row')
  const drafted = await courseVersions(course.id)
  assert.equal(drafted.length, 4, 'and appends the version as a draft')
  assert.deepEqual([drafted.at(-1)!.version.title, drafted.at(-1)!.version._status], ['Second title', 'draft'])
})

test('171e. a restore as draft writes the version as the latest draft over a pending one and leaves the published row as it is', async () => {
  // A restore with `draft` saves a version alone and never writes the row.
  const { options } = await versionsTenant('171e')
  const course = await courses.operations.create({ title: 'Kept 171e', fee: 5, summary: 'Same 171e' }, options)
  await courses.operations.update({ id: course.id, title: 'Published 171e', fee: 6 }, options)
  await courses.operations.update({ id: course.id, title: 'Pending 171e', fee: 7, summary: 'Pending summary 171e' }, { ...options, draft: true })
  const [first] = await courseVersions(course.id)
  const restored = await courses.operations.restoreVersion({ id: first!.id }, { ...options, draft: true })
  assert.deepEqual([restored.title, restored.fee, restored._status], ['Kept 171e', 5, 'draft'], 'it answers the draft it wrote')
  const plain = await courses.operations.findByID({ id: course.id }, options)
  assert.deepEqual([plain?.title, plain?.fee, plain?._status], ['Published 171e', 6, 'published'], 'the plain read is the published row, unchanged')
  const draft = await courses.operations.findByID({ id: course.id }, { ...options, draft: true })
  assert.deepEqual([draft?.title, draft?.fee, draft?.summary, draft?._status], ['Kept 171e', 5, 'Same 171e', 'draft'], 'and the draft read is the restored version, a column it shares with the row included, not the draft that was pending')
  const versions = await courseVersions(course.id)
  assert.deepEqual([versions.length, versions.filter((one) => one.latest).length, versions.at(-1)!.latest], [4, 1, true], 'appended as the one latest version')
})

test('171f. a restore as draft needs findVersions, and a version of another tenant\'s row answers as an absent one', async () => {
  const { options, joined } = await versionsTenant('171f')
  const keys = [
    'courses.findByID', 'courses.update', 'courses.restoreVersion',
    'courses.fields.id', 'courses.fields.title', 'courses.fields.fee', 'courses.fields.createdAt', 'courses.fields.updatedAt', 'courses.fields.organization', 'courses.fields._status',
  ]
  await asas.kayan.roles.operations.create({ name: 'restorer', label: { en: 'Restorer', ar: 'مستعيد' }, permissions: keys }, options)
  const course = await courses.operations.create({ title: 'Mine 171f', fee: 1 }, options)
  await courses.operations.update({ id: course.id, title: 'Mine later 171f' }, options)
  const [first] = await courseVersions(course.id)
  const { actor } = await joined('restorer')
  const refused = await courses.operations.restoreVersion({ id: first!.id }, { actor, draft: true }).catch((thrown: unknown) => thrown)
  assert.ok(refused instanceof AsasError && refused.status === 403, `refused 403 without findVersions: ${String(refused)}`)
  assert.equal(refused.key, 'error.forbidden.permission')
  assert.equal((await courseVersions(course.id)).length, 2, 'and nothing is written')

  const theirs = await versionsTenant('171f-theirs')
  const foreign = await courses.operations.restoreVersion({ id: first!.id }, { ...theirs.options, draft: true }).catch((thrown: unknown) => thrown)
  const absent = await courses.operations.restoreVersion({ id: crypto.randomUUID() }, { ...theirs.options, draft: true }).catch((thrown: unknown) => thrown)
  assert.ok(foreign instanceof AsasError && foreign.status === 404, `another tenant's version is 404: ${String(foreign)}`)
  assert.ok(absent instanceof AsasError)
  assert.deepEqual([foreign.key, foreign.params.operation], [absent.key, absent.params.operation], 'in the words an absent version gets')
  assert.equal((await courseVersions(course.id)).length, 2, 'and nothing is written')

  await asas.kayan.roles.operations.create({ name: 'restorer-keyed', label: { en: 'Restorer keyed', ar: 'مستعيد بمفتاح' }, permissions: [...keys, 'courses.findVersions'] }, options)
  const keyed = await joined('restorer-keyed')
  const restored = await courses.operations.restoreVersion({ id: first!.id }, { actor: keyed.actor, draft: true })
  assert.deepEqual([restored.title, restored._status], ['Mine 171f', 'draft'], 'the same role with findVersions restores as a draft')
  assert.equal((await courseVersions(course.id)).length, 3, 'and the draft is appended')
})

test('171j. a row\'s version moments only rise, so a write onto the row over a pending draft puts the draft above the version it saved, and the sheet\'s previous-version read from the draft finds that version', async () => {
  // The write saves the row's version and appends the draft again in one transaction,
  // usually inside one millisecond, so the clock is held still for that write.
  const { options } = await versionsTenant('171j')
  const course = await courses.operations.create({ title: 'Kept 171j' }, options)
  await courses.operations.update({ id: course.id, title: 'Pending 171j' }, { ...options, draft: true })
  mock.timers.enable({ apis: ['Date'], now: Date.now() })
  try {
    await courses.operations.archive({ id: course.id, reason: 'Done 171j' }, options)
  } finally {
    mock.timers.reset()
  }
  const where = { parent: { equals: course.id } }
  const listed = (await courses.operations.findVersions({ where, sort: '-updatedAt' }, options)).docs
  assert.deepEqual(listed.map((one) => [one.version._status, one.latest]), [['draft', true], ['published', false], ['draft', false], ['published', false]], 'the draft heads the list, then the version the write saved')
  const before = await courses.operations.findVersions({ where: { and: [where, { updatedAt: { less_than: new Date(listed[0]!.updatedAt).toISOString() } }] }, sort: '-updatedAt', limit: 1 }, options)
  assert.deepEqual(before.docs.map((one) => one.id), [listed[1]!.id], 'and the version before the draft is the one the write saved')
})

test('172a. restoring the version a published row holds, or naming the row\'s own id, makes the published copy the latest again, leaves the plain read as it was and deletes no version', async () => {
  const { options } = await versionsTenant('172a')
  const course = await courses.operations.create({ title: 'Published 172a', fee: 5 }, options)
  await courses.operations.update({ id: course.id, title: 'Pending 172a', fee: 6 }, { ...options, draft: true })
  const [published] = await courseVersions(course.id)
  // The version labelled Currently published holds what the row holds, so
  // the restore changes no column and still publishes.
  await courses.operations.restoreVersion({ id: published!.id }, options)
  const restored = await courses.operations.findByID({ id: course.id }, { ...options, draft: true })
  assert.deepEqual([restored?.title, restored?.fee, restored?._status], ['Published 172a', 5, 'published'], 'the draft read is the published copy, and the row is Published again')
  assert.deepEqual(await courseRow(course.id), { title: 'Published 172a', fee: '5', _status: 'published' }, 'the plain read is unchanged')
  assert.deepEqual((await courseVersions(course.id)).map((one) => [one.version.title, one.version._status, one.latest]), [
    ['Published 172a', 'published', false],
    ['Pending 172a', 'draft', false],
    ['Published 172a', 'published', true],
  ], 'a published version is appended over the draft, and no version is deleted')

  await courses.operations.update({ id: course.id, title: 'Pending again 172a' }, { ...options, draft: true })
  await courses.operations.restoreVersion({ id: course.id }, options)
  const discarded = await courses.operations.findByID({ id: course.id }, { ...options, draft: true })
  assert.deepEqual([discarded?.title, discarded?._status], ['Published 172a', 'published'], 'the row\'s own id discards the draft the same way')
  assert.deepEqual(await courseRow(course.id), { title: 'Published 172a', fee: '5', _status: 'published' })
  const versions = await courseVersions(course.id)
  assert.deepEqual([versions.length, versions.at(-1)!.version._status, versions.at(-1)!.latest], [5, 'published', true], 'and appends its published version too')
})

test('172b. the row\'s own id discards a pending draft after max trimmed the published version', async () => {
  const brief = await memoAsas.kayan.briefs.operations.create({ body: 'Published 172b', fee: 1 })
  await memoAsas.kayan.briefs.operations.update({ id: brief.id, body: 'Pending 172b' }, { draft: true })
  const kept = async () => (await db.execute(`select version, latest from _briefs_versions where parent_id = '${brief.id}'`)).rows as { version: Record<string, unknown>; latest: boolean }[]
  assert.deepEqual((await kept()).map((one) => one.version.body), ['Pending 172b'], 'max keeps the draft alone, so no version holds the published copy')
  await memoAsas.kayan.briefs.operations.restoreVersion({ id: brief.id })
  const draft = await memoAsas.kayan.briefs.operations.findByID({ id: brief.id }, { draft: true })
  assert.deepEqual([draft?.body, draft?._status], ['Published 172b', 'published'], 'the draft read is the published copy again')
  assert.deepEqual((await kept()).map((one) => [one.version.body, one.version._status, one.latest]), [['Published 172b', 'published', true]])
})

test('172c. discarding by the row\'s id needs restoreVersion, and an actor without findVersions, another tenant\'s row or a row never published is answered as an absent version', async () => {
  const { options, joined } = await versionsTenant('172c')
  const course = await courses.operations.create({ title: 'Mine 172c', fee: 1 }, options)
  await courses.operations.update({ id: course.id, title: 'Pending 172c' }, { ...options, draft: true })
  const keys = [
    'courses.findByID', 'courses.update', 'courses.restoreVersion',
    'courses.fields.id', 'courses.fields.title', 'courses.fields.fee', 'courses.fields.createdAt', 'courses.fields.updatedAt', 'courses.fields.organization', 'courses.fields._status',
  ]
  await asas.kayan.roles.operations.create({ name: 'discarder', label: { en: 'Discarder', ar: 'متجاهل' }, permissions: keys }, options)
  const keyless = await joined('discarder')
  const { actor: instructor } = await joined('instructor')
  const refused = await courses.operations.restoreVersion({ id: course.id }, { actor: instructor }).catch((thrown: unknown) => thrown)
  assert.ok(refused instanceof AsasError && refused.status === 403, `refused 403 without restoreVersion: ${String(refused)}`)
  assert.equal(refused.key, 'error.forbidden.permission')
  // An actor without findVersions is answered as for an id that is not
  // there, so it cannot tell a row's id from any other.
  const hidden = await courses.operations.restoreVersion({ id: course.id }, { actor: keyless.actor }).catch((thrown: unknown) => thrown)
  const nowhere = await courses.operations.restoreVersion({ id: crypto.randomUUID() }, { actor: keyless.actor }).catch((thrown: unknown) => thrown)
  assert.ok(hidden instanceof AsasError && hidden.status === 404, `refused 404 without findVersions: ${String(hidden)}`)
  assert.ok(nowhere instanceof AsasError)
  assert.deepEqual([hidden.key, hidden.params.operation], [nowhere.key, nowhere.params.operation], 'in the words an absent version gets')
  const theirs = await versionsTenant('172c-theirs')
  const foreign = await courses.operations.restoreVersion({ id: course.id }, theirs.options).catch((thrown: unknown) => thrown)
  const absent = await courses.operations.restoreVersion({ id: crypto.randomUUID() }, theirs.options).catch((thrown: unknown) => thrown)
  assert.ok(foreign instanceof AsasError && foreign.status === 404, `another tenant's row is 404: ${String(foreign)}`)
  assert.ok(absent instanceof AsasError)
  assert.deepEqual([foreign.key, foreign.params.operation], [absent.key, absent.params.operation], 'in the words an absent version gets')
  const never = await courses.operations.create({ title: 'Never 172c' }, { ...options, draft: true })
  const unpublished = await courses.operations.restoreVersion({ id: never.id }, options).catch((thrown: unknown) => thrown)
  assert.ok(unpublished instanceof AsasError && unpublished.status === 404, `a row never published has no published copy to go back to: ${String(unpublished)}`)
  assert.equal((await courseVersions(course.id)).length, 2, 'and nothing is written')
  assert.equal((await courseVersions(never.id)).length, 1)
  await asas.kayan.roles.operations.create({ name: 'seer', label: { en: 'Seer', ar: 'بصير' }, permissions: [...keys, 'courses.findVersions'] }, options)
  const seer = await joined('seer')
  await courses.operations.restoreVersion({ id: course.id }, { actor: seer.actor })
  const restored = await courses.operations.findByID({ id: course.id }, { ...options, draft: true })
  assert.deepEqual([restored?.title, restored?._status], ['Mine 172c', 'published'], 'with findVersions the row\'s id discards the draft')
})

test('172d. a row made with the id of another row\'s version is never what restoreVersion restores by that id, so a Discard on it changes no other row', async () => {
  // Version ids and row ids share one uuid space, and a caller may choose a row's id on
  // create.
  const { options } = await versionsTenant('172d')
  const course = await courses.operations.create({ title: 'Published 172d', fee: 1 }, options)
  await courses.operations.update({ id: course.id, title: 'Pending 172d' }, { ...options, draft: true })
  const [version] = await courseVersions(course.id)
  const squatter = await courses.operations.create({ id: version!.id, title: 'Squatter 172d' } as never, options)
  assert.equal(squatter.id, version!.id, 'the row takes the id it was given')
  const refused = await courses.operations.restoreVersion({ id: version!.id }, options).catch((thrown: unknown) => thrown)
  assert.ok(refused instanceof AsasError && refused.status === 404, `the id names a row, so no version is restored by it: ${String(refused)}`)
  assert.equal((await courseVersions(course.id)).length, 2, 'and nothing is written')
  assert.deepEqual(await courseRow(course.id), { title: 'Published 172d', fee: '1', _status: 'published' })
  assert.equal((await courseRow(squatter.id)).title, 'Squatter 172d')
})

