  const draft = await courses.operations.findByID({ id: course.id }, { ...options, draft: true })
  assert.deepEqual([draft?.title, draft?._status, draft?.archived, draft?.archiveReason], ['Pending 132o', 'draft', true, 'Retired'], 'and the draft keeps its own edit beside the archive')

  const hidden = await courses.operations.create({ title: 'Draft only 132o' }, { ...options, draft: true })
  await courses.operations.archive({ id: hidden.id, reason: 'Never ran' }, options)
