test('132t. a version that cannot be written rolls its row back', async () => {
  const memo = await memoAsas.kayan.memos.operations.create({ body: 'Kept 132t' })
  await db.execute(`alter table _memos_versions add constraint refuse_132t check (parent_id <> '${memo.id}') not valid`)
  try {
    const failed = await memoAsas.kayan.memos.operations.update({ id: memo.id, body: 'Lost 132t' }).catch((thrown: unknown) => thrown)
    assert.ok(failed instanceof Error, 'the write fails with its version')
  } finally {
    await db.execute('alter table _memos_versions drop constraint refuse_132t')
  }
  assert.equal((await db.execute(`select body from memos where id = '${memo.id}'`)).rows[0]!.body, 'Kept 132t', 'and the row is as it was')
})

