test('132aa. a draft request parses against the draft shape through the oRPC plug exactly as through the plain one', async () => {
  const { options } = await versionsTenant('132aa')
  const plugs = {
    orpc: orpcHttp({ context: (_request, actor) => ({ actor, requestId: '132aa' }) })(asas.operations as never),
    plain: fetchHttp({ context: () => ({ requestId: '132aa' }) })(asas.operations as never),
  }
  const answers: Record<string, { status: number; level?: unknown; title?: unknown; _status?: unknown }> = {}
  for (const [name, plug] of Object.entries(plugs)) {
    const response = await plug.handle(new Request('http://test/api/courses/create?draft=true', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ level: 99 }),
    }), async () => options.actor)
    assert.ok(response)
    const body = (await response.json()) as Record<string, unknown>
    answers[name] = { status: response.status, level: body.level, title: body.title, _status: body._status }
  }
  assert.deepEqual(answers.plain, { status: 200, level: 99, title: null, _status: 'draft' }, 'the plain plug saves a draft short of a rule')
  assert.deepEqual(answers.orpc, answers.plain, 'and the oRPC plug answers the same')

  const strays: Record<string, unknown> = {}
  for (const [name, plug] of Object.entries(plugs)) {
    const response = await plug.handle(new Request('http://test/api/courses/create?draft=true', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ level: 'high' }),
    }), async () => options.actor)
    assert.ok(response)
    strays[name] = response.status
  }
  assert.deepEqual(strays, { orpc: 400, plain: 400 }, 'while a value not of its kind is refused on both')
})

