test('132af. an actor holding findVersions points at no draft row, of another tenant or its own, and a bulk filter across a relationship matches no draft row', async () => {
  const mine = await versionsTenant('132af-a')
  const theirs = await versionsTenant('132af-b')
  const hidden = await courses.operations.create({ title: 'Their draft 132af' }, { ...theirs.options, draft: true })
  const startsAt = new Date('2027-04-01T09:00:00Z')
  const pointed = await sessions.operations.create({ course: hidden.id, startsAt }, mine.options).catch((thrown: unknown) => thrown)
  assert.ok(pointed instanceof AsasError && pointed.status === 400, `a session on another tenant's draft course is refused: ${String(pointed)}`)
  assert.equal(pointed.key, 'error.invalid.tenant_reference')

  const secret = await courses.operations.create({ title: 'Secret 132af' }, { ...mine.options, draft: true })
  const own = await sessions.operations.create({ course: secret.id, startsAt }, mine.options).catch((thrown: unknown) => thrown)
  assert.ok(own instanceof AsasError && own.status === 400, `nor at a draft course of its own tenant, for a holder of findVersions too: ${String(own)}`)
  assert.equal(own.key, 'error.invalid.tenant_reference')
  // The session is made while the course is published, and the course is then
  // turned back into a draft no plain read shows.
  await courses.operations.update({ id: secret.id, fee: 1 }, mine.options)
  await sessions.operations.create({ course: secret.id, startsAt }, mine.options)
  await courses.operations.update({ id: secret.id, _status: 'draft' }, mine.options)
  const where = { 'course.title': { equals: 'Secret 132af' } }
  assert.deepEqual((await sessions.operations.updateMany({ where, data: { capacity: 3 } }, mine.options)).docs, [], 'updateMany asks nothing of a course no plain read shows')
  await courses.operations.update({ id: secret.id, _status: 'published' }, mine.options)
  assert.equal((await sessions.operations.updateMany({ where, data: { capacity: 3 } }, mine.options)).docs.length, 1, 'until it is published')
})

