test('132ai. a draft request whose body is no JSON object is refused 400 by the oRPC plug as by the plain one, and the draft word on an operation that saves no draft changes nothing', async () => {
  const { options } = await versionsTenant('132ai')
  const plugs = {
    orpc: orpcHttp({ context: (_request, actor) => ({ actor, requestId: '132ai' }) })(asas.operations as never),
    plain: fetchHttp({ context: () => ({ requestId: '132ai' }) })(asas.operations as never),
  }
  const call = async (plug: keyof typeof plugs, path: string, body: string) => {
    const response = await plugs[plug].handle(new Request(`http://test/api/${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body,
    }), async () => options.actor)
    assert.ok(response)
    const held = (await response.json()) as { code?: unknown; data?: unknown }
    return { status: response.status, code: held.code, data: held.data }
  }
  for (const body of ['null', '1', '"x"', '[]']) {
    const plain = await call('plain', 'courses/create?draft=true', body)
    const drafted = await call('orpc', 'courses/create?draft=true', body)
    assert.deepEqual([plain.status, plain.code], [400, 'BAD_REQUEST'], `the plain plug refuses a draft body of ${body}`)
    assert.deepEqual([drafted.status, drafted.code], [plain.status, plain.code], `and the oRPC plug answers the same status and code for it, never a 500`)
    assert.deepEqual(drafted, await call('orpc', 'courses/create', body), 'which is what it answers for the same body without the draft word')
  }
  const stray = JSON.stringify({ startsAt: 'soon' })
  const worded = await call('orpc', 'sessions/create?draft=true', stray)
  assert.equal(worded.status, 400, 'a kayan that keeps no drafts still refuses a value not of its kind with the draft word')
  assert.deepEqual(worded, await call('orpc', 'sessions/create', stray), 'exactly as without it')
  assert.deepEqual(worded, await call('plain', 'sessions/create?draft=true', stray), 'and as the plain plug does')
})

test('132aj. an id not of the kayan\'s shape is refused 400 by both plugs, with the draft word or without it, before any store is asked', async () => {
  const { options } = await versionsTenant('132aj')
  const plugs = {
    orpc: orpcHttp({ context: (_request, actor) => ({ actor, requestId: '132aj' }) })(asas.operations as never),
    plain: fetchHttp({ context: () => ({ requestId: '132aj' }) })(asas.operations as never),
  }
  const call = async (plug: keyof typeof plugs, path: string, input: unknown, rpc = false) => {
    const response = await plugs[plug].handle(new Request(`http://test/api/${rpc ? 'rpc/' : ''}${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(rpc ? { json: input } : input),
    }), async () => options.actor)
    assert.ok(response)
    const body = (await response.json()) as { json?: unknown }
    const held = (rpc ? body.json : body) as { code?: unknown; data?: unknown }
    return { status: response.status, code: held.code, data: held.data }
  }
  for (const [path, input] of [
    ['sessions/update', { id: 'abc' }],
    ['sessions/delete', { id: 'abc' }],
    ['sessions/findByID', { id: 'abc' }],
    ['courses/update', { id: 'abc' }],
    ['courses/delete', { id: 'abc' }],
    ['courses/archive', { id: 'abc', reason: 'Bad id' }],
    ['courses/findByID', { id: 'abc' }],
    ['courses/findVersionByID', { id: 'abc' }],
    ['courses/restoreVersion', { id: 'abc' }],
  ] as const) {
    const refused = await call('orpc', path, input)
    assert.deepEqual([refused.status, (refused.data as { key?: unknown } | undefined)?.key], [400, 'error.invalid.value'], `${path} without the draft word is refused 400 at the oRPC boundary`)
    assert.deepEqual(await call('orpc', `${path}?draft=true`, input), refused, `${path} with the draft word answers the oRPC plug the same, never a 500`)
    assert.deepEqual(await call('orpc', `${path}?draft=true`, input, true), refused, `and so does the typed protocol`)
    assert.deepEqual(await call('plain', path, input), refused, `the plain plug answers ${path} the same`)
    assert.deepEqual(await call('plain', `${path}?draft=true`, input), refused, `with the draft word too`)
  }
})

const kindedRows = (language: ReturnType<typeof offline>, name: string) =>
  language.defineKayan({
    name,
    access: { create: () => true, read: () => true, update: () => true, delete: () => true },
    fields: {
      ...defaultFields,
      title: { kind: 'text' },
      mail: { kind: 'email' },
      count: { kind: 'number' },
      day: { kind: 'date' },
      at: { kind: 'datetime' },
      done: { kind: 'checkbox' },
      parent: { kind: 'relationship', relationTo: name },
      tags: { kind: 'relationship', relationTo: name, hasMany: true },
    },
    targets: { service: { operations: defaultOperations } },
  })

const kindRefusalOf = async (response: Response) => {
  const body = (await response.json()) as Record<string, unknown>
  const held = (body.json ?? body) as { code?: unknown; data?: { key?: unknown; params?: unknown } }
  return { status: response.status, code: held.code, key: held.data?.key, params: held.data?.params }
}
const kindRefused = (path: string, message: string) =>
  ({ status: 400, code: 'BAD_REQUEST', key: 'error.invalid.value', params: { issues: [{ path, message }] } })
// A build that never connects, so a call that reached the store would be the
// connection's failure and a 500, never the 400 these tests ask for.
const quiet = () => {}
const neverConnected = { http: [fetchHttp({ onError: quiet }), orpcHttp({ api: '/api/orpc', onError: quiet })] } as const

test('169w. a where value its column\'s kind refuses is a 400 at its own path on find, count, updateMany and deleteMany, through both plugs, before any store is asked', async () => {
  const language = offline()
  const built = language.buildAsas({ kayan: [kindedRows(language, 'kindedRows')], ...neverConnected })
  const malformed: [where: object, path: string, message: string][] = [
    [{ id: { equals: 'abc' } }, 'where.id.equals', 'kindedRows.id.invalid'],
    [{ count: { greater_than: 'abc' } }, 'where.count.greater_than', 'kindedRows.count.invalid'],
    [{ count: { equals: '' } }, 'where.count.equals', 'kindedRows.count.invalid'],
    [{ day: { in: ['2026-01-01', '2026-13-01'] } }, 'where.day.in.1', 'kindedRows.day.invalid'],
    [{ at: { less_than: 'not a moment' } }, 'where.at.less_than', 'kindedRows.at.invalid'],
    [{ at: { equals: 'abc 1' } }, 'where.at.equals', 'kindedRows.at.invalid'],
    [{ at: { equals: '1' } }, 'where.at.equals', 'kindedRows.at.invalid'],
    [{ at: { equals: 'June 5' } }, 'where.at.equals', 'kindedRows.at.invalid'],
    [{ at: { equals: '2026-02-30T10:00' } }, 'where.at.equals', 'kindedRows.at.invalid'],
    [{ at: { in: ['2026-10-07T25:00'] } }, 'where.at.in.0', 'kindedRows.at.invalid'],
    [{ done: { equals: 'yes' } }, 'where.done.equals', 'kindedRows.done.invalid'],
    [{ mail: { equals: 5 } }, 'where.mail.equals', 'kindedRows.mail.invalid'],
    [{ or: [{ title: { equals: 'Fine' } }, { parent: { not_equals: 'abc' } }] }, 'where.or.1.parent.not_equals', 'kindedRows.parent.invalid'],
    [{ 'parent.id': { not_in: ['abc'] } }, 'where.parent.id.not_in.0', 'kindedRows.id.invalid'],
    [{ tags: { in: [crypto.randomUUID(), 'abc'] } }, 'where.tags.in.1', 'kindedRows.id.invalid'],
    [{ 'tags.count': { less_than: 'abc' } }, 'where.tags.count.less_than', 'kindedRows.count.invalid'],
  ]
  for (const operation of ['find', 'count', 'updateMany', 'deleteMany']) {
    const input = (where: object) => operation === 'updateMany' ? { where, data: { title: 'Changed' } } : { where }
    for (const prefix of ['/api', '/api/orpc']) {
      for (const [where, path, message] of malformed) {
        assert.deepEqual(
          await kindRefusalOf(await posted(built, `${prefix}/kindedRows/${operation}`, input(where))),
          kindRefused(path, message),
          `${prefix} ${operation} ${JSON.stringify(where)} is refused at ${path}, never a 500`,
        )
      }
      const reached = await posted(built, `${prefix}/kindedRows/${operation}`, input({ id: { equals: crypto.randomUUID() } }))
      assert.equal(reached.status, 500, `a well-formed where on ${prefix} ${operation} does reach the store, which this build cannot connect to, so the 400s above were answered before it`)
    }
  }
})

test('169w3. a where on a number id, on a localized column and on findVersions is held to its column\'s kind as well, before any store is asked', async () => {
  const language = reporting(defineMithaq({ locales: ['ar', 'en'] as const, arkan: [base, versionsRukn({ max: 100 })], targets: offlineTargets() }))
  const numbered = language.defineKayan({
    name: 'numberedRows',
    access: { create: () => true, read: () => true, update: () => true, delete: () => true },
    fields: {
      ...defaultFields,
      id: { kind: 'number' },
      price: { kind: 'number', rules: { localized: true } },
    },
    targets: { service: { operations: defaultOperations } },
  })
  const versioned = language.defineKayan({
    name: 'versionedRows',
    access: { create: () => true, read: () => true, update: () => true, delete: () => true },
    fields: { ...defaultFields, title: { kind: 'text' } },
    targets: { service: { operations: { ...defaultOperations, ...versionOperations } }, versions: {} },
  })
  const built = language.buildAsas({ kayan: [numbered, versioned], ...neverConnected })
  for (const [path, where, at, message] of [
    ['numberedRows/find', { id: { equals: 1.5 } }, 'where.id.equals', 'numberedRows.id.invalid'],
    ['numberedRows/count', { id: { in: [1, 3e9] } }, 'where.id.in.1', 'numberedRows.id.invalid'],
    ['numberedRows/find', { 'price.en': { greater_than: 'abc' } }, 'where.price.en.greater_than', 'numberedRows.price.invalid'],
    ['versionedRows/findVersions', { parent: { equals: 'abc' } }, 'where.parent.equals', '_versionedRows_versions.parent.invalid'],
    ['versionedRows/findVersions', { id: { equals: 'abc' } }, 'where.id.equals', '_versionedRows_versions.id.invalid'],
    ['versionedRows/findVersions', { createdAt: { greater_than: 'nope' } }, 'where.createdAt.greater_than', '_versionedRows_versions.createdAt.invalid'],
  ] as const) {
    for (const prefix of ['/api', '/api/orpc']) {
      assert.deepEqual(
        await kindRefusalOf(await posted(built, `${prefix}/${path}`, { where })),
        kindRefused(at, message),
        `${prefix}/${path} ${JSON.stringify(where)} is refused at ${at}, never a 500`,
      )
    }
  }
  for (const [path, where] of [
    ['numberedRows/find', { id: { equals: 2147483647 } }],
    ['numberedRows/find', { 'price.en': { equals: '5' } }],
    ['versionedRows/findVersions', { parent: { equals: crypto.randomUUID() } }],
  ] as const) {
    assert.equal((await posted(built, `/api/${path}`, { where })).status, 500, `${path} ${JSON.stringify(where)} is well-formed, so it reaches the store this build cannot connect to`)
  }
})

test('169w4. a where value of its column\'s kind reads as it did, and a number or a checkbox sent as text is read as one, as Payload reads it', async () => {
  const language = online()
  const built = language.buildAsas({ kayan: [kindedRows(language, 'kindedReads')], http: [fetchHttp()] })
  await built.connect()
  const rows = built.kayan.kindedReads!.operations
  const first = await rows.create({ title: 'First', mail: 'first@example.com', count: 3, day: '2026-01-02', at: new Date('2026-01-02T09:30:00Z'), done: true })
  const second = await rows.create({ title: 'Second', count: 5, parent: first.id, tags: [first.id] })
  const both = [first.id, second.id].sort()
  const found = async (where: object) => ((await rows.find({ where } as never)).docs as { id: string }[]).map((row) => row.id).sort()
  assert.deepEqual(await found({ id: { equals: first.id } }), [first.id])
  assert.deepEqual(await found({ count: { greater_than: 4 } }), [second.id])
  assert.deepEqual(await found({ count: { greater_than: '4' } }), [second.id], 'a number sent as text is read as the number')
  assert.deepEqual(await found({ count: { in: ['3', 5] } }), both)
  assert.deepEqual(await found({ day: { in: ['2026-01-02', null] } }), both)
  assert.deepEqual(await found({ at: { greater_than_equal: '2026-01-02T09:30' } }), [first.id], 'a zone-less moment is the store\'s to read, as it was')
  assert.deepEqual(await found({ at: { equals: '2026-01-02 09:30:00' } }), [first.id], 'and so is one written with a space')
  assert.deepEqual(await found({ at: { equals: '2026-01-02T09:30:00.000Z' } }), [first.id], 'and an ISO instant')
  assert.deepEqual(await found({ at: { equals: '2026-01-02T12:30:00+03:00' } }), [first.id], 'and a moment with its offset')
  assert.deepEqual(await found({ at: { equals: '2026-01-02T12:30:00+0300' } }), [first.id], 'written without the colon too')
  assert.deepEqual(await found({ at: { equals: new Date('2026-01-02T09:30:00Z') } }), [first.id])
  assert.deepEqual(await found({ done: { equals: true } }), [first.id])
  assert.deepEqual(await found({ done: { equals: 'TRUE' } }), [first.id], 'a checkbox sent as text is read as the boolean')
  assert.deepEqual(await found({ mail: { not_equals: '' } }), [first.id], 'an email is compared as text, its format unasked')
  assert.deepEqual(await found({ mail: { equals: 'first' } }), [])
  assert.deepEqual(await found({ parent: { equals: null } }), [first.id])
  assert.deepEqual(await found({ 'parent.title': { equals: 'First' } }), [second.id])
  assert.deepEqual(await found({ tags: { in: [first.id] } }), [second.id])
  assert.deepEqual(await found({ or: [{ 'parent.id': { in: [first.id] } }, { done: { exists: true } }] }), both)
  assert.equal((await rows.count({ where: { count: { less_than_equal: '5' } } } as never)).totalDocs, 2)
  assert.equal(((await rows.updateMany({ where: { id: { equals: second.id } }, data: { title: 'Changed' } } as never)) as { docs: unknown[] }).docs.length, 1)
  assert.equal(((await rows.deleteMany({ where: { id: { in: [second.id] } } } as never)) as { docs: unknown[] }).docs.length, 1)
})

test('185b. a course\'s details is Lexical\'s editor state in a jsonb column, read back in process and served, a list searches the words of its text alone, and no other comparison reaches the column', async () => {
  const options = await tenantOptions()
  const cookie = signedIn.get('cookie') ?? ''
  const text = (words: string, format = 0) => ({ type: 'text', version: 1, text: words, format, detail: 0, mode: 'normal', style: '' })
  const details = {
    root: {
      type: 'root' as const, version: 1, direction: 'ltr', format: '', indent: 0,
      children: [
        { type: 'heading', tag: 'h2', version: 1, direction: 'ltr', format: '', indent: 0, children: [text('Quantum')] },
        { type: 'paragraph', version: 1, direction: 'ltr', format: '', indent: 0, textFormat: 0, textStyle: '', children: [text('Covers '), text('entanglement', 1)] },
      ],
    },
  }
  const course = await courses.operations.create({ title: 'Rich details 185b', details }, options)
  assert.deepEqual(course.details, details, 'the write answers the value it stored')
  const { rows } = await db.execute(`select jsonb_typeof(details) as type from courses where id = '${course.id}'`)
  assert.deepEqual(rows, [{ type: 'object' }], 'held as one jsonb object')
  assert.deepEqual((await courses.operations.findByID({ id: course.id }, options))?.details, details, 'and read back the same in process')
  for (const call of [apiCall, rpcCall]) {
    const served = await call('courses/findByID', { id: course.id }, { cookie })
    assert.equal(served.status, 200)
    assert.deepEqual((await bodyOf(served)).details, details, 'and served, on either arm')
  }

  // The search a list folds in, one `like` per word, over the text alone: a
  // word of the text finds the row, while a key or a node type of the JSON
  // around it finds nothing.
  const found = async (where: Record<string, unknown>) => (await courses.operations.find({ where: { and: [{ id: { equals: course.id } }, where as never] } }, options)).docs.length
  assert.equal(await found({ details: { like: 'quantum ENTANGLE' } }), 1, 'words of its text find it, in any case')
  assert.equal(await found({ details: { like: 'paragraph' } }), 0, 'a node type does not')
  assert.equal(await found({ details: { contains: 'version' } }), 0, 'and neither does a key')
  assert.equal(await found({ details: { exists: true } }), 1, 'it exists')
  for (const where of [{ details: { equals: 'Quantum' } }, { details: { in: ['Quantum'] } }, { details: { greater_than: 'a' } }]) {
    const refused = await courses.operations.find({ where }, options).catch((thrown: unknown) => thrown)
    assert.ok(refused instanceof AsasError && refused.status === 400, `${Object.keys(where.details)[0]} on rich text is the caller's 400, never the driver's 500`)
  }
  const sorted = await courses.operations.find({ sort: 'details' }, options).catch((thrown: unknown) => thrown)
  assert.ok(sorted instanceof AsasError && sorted.status === 400, 'and a page cannot be ordered by it')

  // The audit log lists the field where its value changed and nowhere else:
  // jsonb hands back an object's keys in its own order on both sides, so a
  // write that never named the field is no change of it.
  await courses.operations.update({ id: course.id, title: 'Rich details 185b, renamed' }, options)
  const edited = { root: { ...details.root, children: [details.root.children[0]!] } }
  await courses.operations.update({ id: course.id, details: edited }, options)
  const logged = ((await db.execute(`select changes from audit_log where record = '${course.id}' and operation = 'update' order by created_at`)).rows as { changes: string }[])
    .map((row) => Object.keys(JSON.parse(row.changes) as object).filter((name) => name !== 'updatedAt').sort())
  assert.deepEqual(logged, [['title'], ['details']], 'a rename lists the title alone, and an edit of the details lists them')
})

test('185f. a draft holds a course\'s details in its version alone, a draft read answers them, and a restore puts an older version\'s details back on the row', async () => {
  const { options } = await versionsTenant('185f')
  const words = (text: string) => ({ root: { type: 'root' as const, children: [{ type: 'paragraph', children: [{ type: 'text', text }] }] } })
  const course = await courses.operations.create({ title: 'Versioned details', details: words('First words') }, options)
  await courses.operations.update({ id: course.id, details: words('Drafted words') }, { ...options, draft: true })
  assert.deepEqual((await courses.operations.findByID({ id: course.id }, options))?.details, words('First words'), 'the row keeps the published details')
  assert.deepEqual((await courses.operations.findByID({ id: course.id }, { ...options, draft: true }))?.details, words('Drafted words'), 'and a draft read answers the drafted ones')
  await courses.operations.update({ id: course.id, details: words('Published words') }, options)
  const [first] = await courseVersions(course.id)
  assert.deepEqual(first!.version.details, words('First words'), 'each version keeps the details it was saved with')
  const restored = await courses.operations.restoreVersion({ id: first!.id }, options)
  assert.deepEqual(restored.details, words('First words'), 'and a restore puts them back on the row')
})

test('185h. a draft save and an autosave of a course\'s details run the same walk and parse a publish does, so a value refused there is a 400 and no version of it is stored; only required is left to the publish', async () => {
  const { options } = await versionsTenant('185h')
  const words = (text: string) => ({ root: { type: 'root' as const, children: [{ type: 'paragraph', children: [{ type: 'text', text }] }] } })
  const course = await courses.operations.create({ title: 'Drafted details', details: words('Kept') }, options)
  const before = (await courseVersions(course.id)).length
  const linkTo = (url: string) => ({ root: { type: 'root' as const, children: [{ type: 'paragraph', children: [{ type: 'link', url, children: [{ type: 'text', text: 'x' }] }] }] } })
  const refused: [string, unknown][] = [
    ['a node no class registers', { root: { type: 'root', children: [{ type: 'mention' }] } }],
    ['a javascript: link', linkTo('javascript:alert(1)')],
    ['a style', { root: { type: 'root', children: [{ type: 'paragraph', children: [{ type: 'text', text: 'x', style: 'color: red' }] }] } }],
    ['children that are no list', { root: { type: 'root', children: [{ type: 'paragraph', children: {} }] } }],
  ]
  for (const [what, details] of refused) {
    for (const save of [{ draft: true }, { draft: true, autosave: true }]) {
      const draft = await courses.operations.update({ id: course.id, details } as never, { ...options, ...save }).catch((thrown: unknown) => thrown)
      assert.ok(draft instanceof AsasError && draft.status === 400, `${what} is a 400 on ${JSON.stringify(save)}: ${String(draft)}`)
      const made = await courses.operations.create({ title: `Draft ${what}`, details } as never, { ...options, ...save }).catch((thrown: unknown) => thrown)
      assert.ok(made instanceof AsasError && made.status === 400, `and on a draft create, ${JSON.stringify(save)}`)
    }
  }
  assert.equal((await courseVersions(course.id)).length, before, 'and no version of any of them is stored')
  // Only `required` waits for the publish: a blank draft of a required rich text would
  // still be a draft. The template's details are not required, so a blank one saves as a
  // draft.
  const blank = await courses.operations.update({ id: course.id, details: { root: { type: 'root', children: [] } } }, { ...options, draft: true })
  assert.deepEqual(blank.details, { root: { type: 'root', children: [] } }, 'a blank draft is a draft')
})

test('186m. the template\'s media takes an image through its own storage, a course points at it as its cover, the audit log records its file columns, and it is not deleted while a course names it', async () => {
  const options = await tenantOptions()
  const cookie = signedIn.get('cookie') ?? ''
  const png = Uint8Array.from(Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==', 'base64'))
  const asked = await asas.handler(new Request('http://test/api/media/uploadInstructions', {
    method: 'POST',
    headers: { cookie, 'content-type': 'application/json' },
    body: JSON.stringify({ filename: 'cover.png', filesize: png.length, mimeType: 'image/png' }),
  }))
  assert.equal(asked.status, 200, await asked.clone().text())
  const { request, file } = await asked.json() as { request: { url: string; headers: Record<string, string> }; file: { uploadReference: { key: string } } }
  assert.equal((await asas.handler(new Request(new URL(request.url, 'http://test'), { method: 'PUT', headers: request.headers, body: png }))).status, 204)
  const media = asas.kayan.media.operations
  const image = await media.create({ uploadReference: file.uploadReference, alt: { en: 'A cover', ar: 'غلاف' } } as never, options) as Record<string, unknown>
  assert.equal(image.key, file.uploadReference.key)
  assert.equal(image.organization, organizationId)
  assert.equal(image.storage, 'local')
  const served = await asas.handler(new Request(`http://test${String(image.url)}`, { headers: { cookie } }))
  assert.equal(served.status, 200)
  assert.equal(served.headers.get('x-content-type-options'), 'nosniff')

  const entry = (await db.select().from(tables.auditLog)).find((row) => row.kayan === 'media' && row.record === image.id)
  assert.ok(entry, 'the create is in the audit log')
  assert.match(String(entry.changes), new RegExp(String(image.key).replaceAll('/', '\\/')), 'with its key among the columns it records')

  const course = await courses.operations.create({ title: 'Covered', fee: 10, cover: image.id } as never, options)
  assert.equal(course.cover, image.id)
  // A file still named by a row stays: the upload restricts, never sets null.
  const refused = await media.delete({ id: image.id } as never, options).then(() => undefined, (error: unknown) => error)
  assert.ok(refused instanceof AsasError)
  assert.equal(refused.status, 409)
  assert.equal(refused.key, 'error.conflict.referenced')
  assert.deepEqual(refused.params, { kayan: 'media', by: 'courses' }, 'naming the kayan whose row still points at it')
  assert.equal((await courses.operations.findByID({ id: course.id }, options))!.cover, image.id)

  await courses.operations.delete({ id: course.id }, options)
  await media.delete({ id: image.id } as never, options)
  const gone = await stat(join(process.env.STORAGE_DIR!, String(image.key))).then(() => false, () => true)
  assert.ok(gone, 'the object went after the commit')
  await rm(process.env.STORAGE_DIR!, { recursive: true, force: true })
})

test('186o. a file held in a gallery of many is not deleted while the gallery names it, and the gallery may still be', async () => {
  const store = galleryAsas.targets.drizzle as unknown as {
    insert(args: { tx: unknown; kayan: string; data: Record<string, unknown> }): Promise<Record<string, unknown>>
    transaction<Result>(fn: (tx: unknown) => Promise<Result>): Promise<Result>
  }
  const written = new Date()
  const image = await store.transaction((tx) =>
    store.insert({ tx, kayan: 'probeMedia', data: { createdAt: written, updatedAt: written, filename: 'a.png', mimeType: 'image/png', filesize: 67, key: `probe/${crypto.randomUUID()}/a.png`, storage: 'local' } }),
  )
  const gallery = await galleryAsas.kayan.galleries.operations.create({ images: [image.id] } as never)
  const refused = await galleryAsas.kayan.probeMedia.operations.delete({ id: image.id } as never).then(() => undefined, (error: unknown) => error)
  assert.ok(refused instanceof AsasError, 'the delete is refused')
  assert.equal(refused.status, 409)
  assert.equal(refused.key, 'error.conflict.referenced')
  assert.deepEqual(refused.params, { kayan: 'probeMedia', by: 'galleries' }, 'naming the kayan whose join table still points at it')
  assert.deepEqual((await galleryAsas.kayan.galleries.operations.findByID({ id: gallery.id }))!.images, [image.id], 'and the gallery keeps the file')
  await galleryAsas.kayan.galleries.operations.delete({ id: gallery.id })
  await galleryAsas.kayan.probeMedia.operations.delete({ id: image.id } as never)
})

test('208. a tag update carrying the instant its caller read is refused 409 once the tag has changed, and of two writers holding one read the row lock lets exactly one win, through both plugs', async () => {
  const options = await tenantOptions()
  const cookie = signedIn.get('cookie') ?? ''
  const { tags } = asas.kayan
  const made = await tags.operations.create({ name: { en: 'Read once', ar: 'قرئ مرة' } }, options)
  try {
    await setTimeout(5)
    const settled = await Promise.allSettled(
      ['one', 'two'].map((name) => tags.operations.update({ id: made.id, name: { en: name, ar: name }, expectedUpdatedAt: made.updatedAt }, options)),
    )
    const lost = settled.filter((one) => one.status === 'rejected')
    assert.equal(settled.filter((one) => one.status === 'fulfilled').length, 1, 'one writer wins')
    assert.equal(lost.length, 1, 'and the other is refused')
    const error = lost[0]!.reason
    assert.ok(error instanceof AsasError)
    assert.equal(error.status, 409)
    assert.equal(error.key, 'error.conflict.stale')
    const held = (await tags.operations.findByID({ id: made.id }, options))!
    assert.ok(['one', 'two'].includes((held.name as { en: string }).en), 'the row holds the winner\'s write')

    for (const call of [rpcCall, apiCall]) {
      const stale = await call('tags/update', { id: made.id, name: { en: 'late', ar: 'late' }, expectedUpdatedAt: made.updatedAt.toISOString() }, { cookie })
      assert.equal(stale.status, 409, 'a stale instant reaches the wire as a 409')
      assert.deepEqual((await bodyOf(stale)).data, { key: 'error.conflict.stale', params: { kayan: 'tags' } }, 'carrying the key where the protocol puts it')
      const read = (await tags.operations.findByID({ id: made.id }, options))!
      const fresh = await call('tags/update', { id: made.id, name: { en: 'fresh', ar: 'fresh' }, expectedUpdatedAt: read.updatedAt.toISOString() }, { cookie })
      assert.equal(fresh.status, 200, 'and the instant just read is taken')
      await fresh.body?.cancel()
      await setTimeout(5)
    }
    const kept = await db.execute(`select * from tags where id = '${made.id}'`)
    assert.ok(!('expectedUpdatedAt' in kept.rows[0]!) && !('expected_updated_at' in kept.rows[0]!), 'the key is never a column')
    const logged = (await db.execute(`select changes from audit_log where record = '${made.id}' and operation = 'update'`)).rows as { changes: string }[]
    assert.ok(logged.length > 0, 'the updates were logged')
    assert.ok(logged.every((entry) => !entry.changes.includes('expectedUpdatedAt')), 'and no entry records the key as a change')
  } finally {
    await tags.operations.delete({ id: made.id }, options)
  }
})

test('223. a course draft save, autosave, publish and discard carrying the instant its caller read is refused 409 once another writer saved, and taken when it is fresh, through both plugs', async () => {
  const { options, headers } = await versionsTenant('223')
  const cookie = new Headers(headers).get('cookie') ?? ''
  const course = await courses.operations.create({ title: 'Read once 223' }, options)
  const read = async () => (await courses.operations.findByID({ id: course.id }, { ...options, draft: true }))!.updatedAt.toISOString()
  const opened = await read()
  await setTimeout(5)
  const first = await apiCall('courses/update?draft=true', { id: course.id, title: 'First tab', expectedUpdatedAt: opened }, { cookie })
  assert.equal(first.status, 200, `a draft save holding the instant just read is taken: ${JSON.stringify(await first.clone().json())}`)
  assert.equal(await read(), (await bodyOf(first)).updatedAt, 'and answers the instant a draft reader now reads')
  const kept = await courseVersions(course.id)
  for (const call of [apiCall, rpcCall]) {
    for (const query of ['?draft=true', '?draft=true&autosave=true', '']) {
      const stale = await call(`courses/update${query}`, { id: course.id, title: 'Late tab', expectedUpdatedAt: opened }, { cookie })
      assert.equal(stale.status, 409, `a stale ${query || 'publish'} is refused 409`)
      assert.deepEqual((await bodyOf(stale)).data, { key: 'error.conflict.stale', params: { kayan: 'courses' } }, `carrying the key, ${query || 'publish'}`)
    }
  }
  assert.deepEqual(await courseVersions(course.id), kept, 'no refused write touched a version')
  assert.equal((await courseRow(course.id)).title, 'Read once 223', 'nor the row')
  for (const [call, query] of [[apiCall, '?draft=true&autosave=true'], [rpcCall, '?draft=true&autosave=true'], [apiCall, '?draft=true'], [rpcCall, '']] as const) {
    await setTimeout(5)
    const fresh = await call(`courses/update${query}`, { id: course.id, title: `Fresh ${query || 'publish'}`, expectedUpdatedAt: await read() }, { cookie })
    assert.equal(fresh.status, 200, `a fresh ${query || 'publish'} is taken: ${JSON.stringify(await fresh.clone().json())}`)
  }
  assert.equal((await courseRow(course.id)).title, 'Fresh publish', 'the fresh publish reached the row')
  assert.equal((await apiCall('courses/update', { id: course.id, title: 'No instant' }, { cookie })).status, 200, 'and a caller who sends no instant is not guarded')
  for (const query of ['?draft=true', '?draft=true&autosave=true', '']) {
    const stray = await apiCall(`courses/update${query}`, { id: course.id, title: 'Stray', bogus: 1 }, { cookie })
    assert.equal(stray.status, 400, `the widened input still refuses a key it does not name, ${query || 'publish'}`)
    assert.match(JSON.stringify(await bodyOf(stray)), /Unrecognized key: \\"bogus\\"/)
  }

  // Discard on a New page deletes the draft its autosave made, holding the
  // instant of its last autosave, so another person's draft edit since keeps it.
  const made = await bodyOf(await apiCall('courses/create?draft=true&autosave=true', { title: 'New 223' }, { cookie }))
  await setTimeout(5)
  const other = await bodyOf(await apiCall('courses/update?draft=true&autosave=true', { id: made.id, title: 'Other person', expectedUpdatedAt: made.updatedAt }, { cookie }))
  const refused = await apiCall('courses/delete', { id: made.id, expectedUpdatedAt: made.updatedAt }, { cookie })
  assert.equal(refused.status, 409, 'a stale discard is refused 409')
  assert.deepEqual((await bodyOf(refused)).data, { key: 'error.conflict.stale', params: { kayan: 'courses' } }, 'carrying the key')
  assert.equal((await db.execute(`select id from courses where id = '${String(made.id)}'`)).rows.length, 1, 'and the draft is kept')
  assert.equal((await apiCall('courses/delete', { id: made.id, expectedUpdatedAt: other.updatedAt }, { cookie })).status, 200, 'a fresh discard deletes it')
  await courses.operations.delete({ id: course.id }, options)
})

test('223d. a course restore carrying the instant its caller read, Discard changes or a version restored onto the row or as a draft, is refused 409 once another writer saved a newer draft, which is kept, and taken when it is fresh, through both plugs', async () => {
  const { options, headers } = await versionsTenant('223d')
  const cookie = new Headers(headers).get('cookie') ?? ''
  const course = await courses.operations.create({ title: 'Published 223d' }, options)
  const read = async () => (await courses.operations.findByID({ id: course.id }, { ...options, draft: true }))!
  const opened = (await read()).updatedAt.toISOString()
  await setTimeout(5)
  await courses.operations.update({ id: course.id, title: 'Newer draft 223d', expectedUpdatedAt: new Date(opened) } as never, { ...options, draft: true })
  const [first] = (await courses.operations.findVersions({ where: { parent: { equals: course.id } }, sort: 'updatedAt', limit: 1 }, options)).docs
  const kept = await courseVersions(course.id)
  for (const call of [apiCall, rpcCall]) {
    for (const [what, path, id] of [['Discard changes', 'courses/restoreVersion', course.id], ['a version restore', 'courses/restoreVersion', first!.id], ['a draft restore', 'courses/restoreVersion?draft=true', first!.id]] as const) {
      const stale = await call(path, { id, expectedUpdatedAt: opened }, { cookie })
      assert.equal(stale.status, 409, `a stale ${what} is refused 409: ${JSON.stringify(await stale.clone().json())}`)
      assert.deepEqual((await bodyOf(stale)).data, { key: 'error.conflict.stale', params: { kayan: 'courses' } }, `carrying the key, ${what}`)
    }
  }
  assert.deepEqual(await courseVersions(course.id), kept, 'no refused restore wrote a version')
  assert.equal((await read()).title, 'Newer draft 223d', 'and the newer draft is kept')
  const fresh = await apiCall('courses/restoreVersion', { id: course.id, expectedUpdatedAt: (await read()).updatedAt.toISOString() }, { cookie })
  assert.equal(fresh.status, 200, `a fresh Discard changes restores: ${JSON.stringify(await fresh.clone().json())}`)
  assert.equal((await read()).title, 'Published 223d', 'back to the published copy')
  await setTimeout(5)
  const again = await rpcCall('courses/restoreVersion', { id: first!.id, expectedUpdatedAt: (await read()).updatedAt.toISOString() }, { cookie })
  assert.equal(again.status, 200, 'a fresh version restore is taken over rpc too')
  assert.equal((await apiCall('courses/restoreVersion', { id: course.id, bogus: 1 }, { cookie })).status, 400, 'and a key the restore does not name is refused')
  await courses.operations.delete({ id: course.id }, options)
})

