test('220d. a request to an auth arm whose client went away while sending its body is answered without a fault and logs nothing, and a body that fails on its own is still a fault', async () => {
  const reading = (abort: boolean) => {
    const controller = new AbortController()
    const body = new ReadableStream({
      start: (stream) => stream.enqueue(new TextEncoder().encode('{"email":')),
      pull: () => {
        if (abort) controller.abort()
        throw new Error('aborted')
      },
    })
    return new Request('http://test/api/auth/user/sign-in/email', { method: 'POST', headers: { 'content-type': 'application/json' }, body, duplex: 'half', signal: controller.signal } as RequestInit)
  }
  const logged = mock.method(console, 'error', () => {})
  try {
    const answer = await asas.handler(reading(true))
    assert.equal(answer.status, 499, 'a client that went away is answered, not handed to the provider')
    assert.equal(logged.mock.callCount(), 0, 'and nothing is logged as a server error')
  } finally {
    logged.mock.restore()
  }
  await assert.rejects(() => asas.handler(reading(false)), /aborted/, 'a body that failed with the client still there is a fault the host reports')
})

const roleTenant = async (slug: string) => {
  const owner = await signedUp(`${slug}-owner`)
  const organization = await server.api.createOrganization({ body: { name: slug, slug }, headers: owner.headers })
  await assignRole(organization!.id, owner.id, 'administrator')
  const member = async (role: 'registrar' | 'instructor' | 'student') => {
    const person = await signedUp(`${slug}-${role}`)
    await server.api.addMember({ body: { userId: person.id, organizationId: organization!.id, role: 'member' } })
    await server.api.setActiveOrganization({ body: { organizationId: organization!.id }, headers: person.headers })
    await assignRole(organization!.id, person.id, role)
    return person
  }
  const people = { admin: owner, registrar: await member('registrar'), instructor: await member('instructor'), student: await member('student') }
  return {
    organization: organization!.id,
    people,
    options: { actor: (await asas.auth.actor(owner.headers)) as never },
    as: async (who: keyof typeof people, path: string, input: unknown) => {
      const answer = await apiCall(path, input, { cookie: people[who].headers.get('cookie') ?? '' })
      return { status: answer.status, body: await bodyOf(answer) }
    },
    file: async (who: keyof typeof people, id: string) => {
      const answer = await asas.handler(new Request(`http://test/api/media/file/${id}`, { headers: { cookie: people[who].headers.get('cookie') ?? '' } }))
      await answer.body?.cancel()
      return answer.status
    },
  }
}

const uploadedImage = async (headers: Headers, options: { actor: never }, filename: string) => {
  const png = Uint8Array.from(Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==', 'base64'))
  const asked = await asas.handler(new Request('http://test/api/media/uploadInstructions', {
    method: 'POST',
    headers: { cookie: headers.get('cookie') ?? '', 'content-type': 'application/json' },
    body: JSON.stringify({ filename, filesize: png.length, mimeType: 'image/png' }),
  }))
  assert.equal(asked.status, 200, await asked.clone().text())
  const { request, file } = await asked.json() as { request: { url: string; headers: Record<string, string> }; file: { uploadReference: { key: string } } }
  assert.equal((await asas.handler(new Request(new URL(request.url, 'http://test'), { method: 'PUT', headers: request.headers, body: png }))).status, 204)
  return (await asas.kayan.media.operations.create({ uploadReference: file.uploadReference, alt: { en: filename, ar: filename } } as never, options) as { id: string }).id
}

test('227a. an archived course is read by no student or instructor, in find, findByID, count and a filter across a session\'s course, and the administrator and the registrar still read it', async () => {
  const tenant = await roleTenant('archived-227a')
  const open = await courses.operations.create({ title: 'Open 227a' }, tenant.options)
  const shut = await courses.operations.create({ title: 'Shut 227a' }, tenant.options)
  await courses.operations.archive({ id: shut.id, reason: 'Retired' }, tenant.options)
  await sessions.operations.create({ course: shut.id, startsAt: new Date('2027-01-01T09:00:00Z') }, tenant.options)
  const where = { title: { like: '227a' } }
  for (const who of ['student', 'instructor'] as const) {
    const listed = await tenant.as(who, 'courses/find', { where })
    assert.equal(listed.status, 200)
    assert.deepEqual((listed.body.docs as { id: string }[]).map((one) => one.id), [open.id], `${who}: find leaves the archived course out`)
    assert.equal((await tenant.as(who, 'courses/count', { where })).body.totalDocs, 1, `${who}: and so does count`)
    assert.equal((await tenant.as(who, 'courses/findByID', { id: shut.id })).status, 404, `${who}: findByID answers 404, as a missing row does`)
    assert.equal((await tenant.as(who, 'courses/findByID', { id: open.id })).status, 200, `${who}: an open course still reads`)
    const asked = await tenant.as(who, 'courses/find', { where: { archived: { equals: true } } })
    assert.equal(asked.body.totalDocs, 0, `${who}: asking for archived courses by name finds none`)
  }
  const across = await tenant.as('instructor', 'sessions/find', { where: { 'course.title': { equals: 'Shut 227a' } } })
  assert.equal(across.body.totalDocs, 0, 'a filter across a session\'s course matches no archived course')
  // The administrator holds `courses.archive`; the registrar holds
  // `screen.dashboard`, where the catalogue is run.
  for (const who of ['admin', 'registrar'] as const) {
    assert.equal((await tenant.as(who, 'courses/find', { where })).body.totalDocs, 2, `${who}: reads both`)
    assert.equal((await tenant.as(who, 'courses/findByID', { id: shut.id })).status, 200, `${who}: and opens the archived one`)
    assert.equal((await tenant.as(who, 'sessions/find', { where: { 'course.title': { equals: 'Shut 227a' } } })).body.totalDocs, 1, `${who}: and finds its session across it`)
  }
})

test('227b. a role whose image reads are a course\'s cover reads only the covers of courses it may read, in find, findByID and the file route, and the administrator reads every image', async () => {
  const tenant = await roleTenant('covers-227b')
  const { headers } = tenant.people.admin
  const [shown, archived, drafted, loose] = [
    await uploadedImage(headers, tenant.options, 'shown.png'),
    await uploadedImage(headers, tenant.options, 'archived.png'),
    await uploadedImage(headers, tenant.options, 'drafted.png'),
    await uploadedImage(headers, tenant.options, 'loose.png'),
  ]
  await courses.operations.create({ title: 'Shown 227b', cover: shown }, tenant.options)
  const shut = await courses.operations.create({ title: 'Archived 227b', cover: archived }, tenant.options)
  await courses.operations.archive({ id: shut.id, reason: 'Retired' }, tenant.options)
  await courses.operations.create({ title: 'Drafted 227b', cover: drafted }, { ...tenant.options, draft: true })
  for (const who of ['student', 'instructor'] as const) {
    const listed = await tenant.as(who, 'media/find', { limit: 100 })
    assert.equal(listed.status, 200, JSON.stringify(listed.body))
    assert.deepEqual((listed.body.docs as { id: string }[]).map((one) => one.id), [shown], `${who}: find lists the cover of the one course it reads`)
    assert.equal((await tenant.as(who, 'media/findByID', { id: shown })).status, 200)
    assert.equal(await tenant.file(who, shown), 200, `${who}: and the file route serves it`)
    for (const [id, what] of [[archived, 'an archived course\'s cover'], [drafted, 'a draft course\'s cover'], [loose, 'an image no course names']] as const) {
      assert.equal((await tenant.as(who, 'media/findByID', { id })).status, 404, `${who}: ${what} answers 404`)
      assert.equal(await tenant.file(who, id), 404, `${who}: and its file too`)
    }
  }
  const all = await tenant.as('admin', 'media/find', { limit: 100 })
  assert.deepEqual(new Set((all.body.docs as { id: string }[]).map((one) => one.id)), new Set([shown, archived, drafted, loose]), 'the administrator reads every image')
  assert.equal(await tenant.file('admin', loose), 200, 'an image no course names included')
})

test('227f. the media feature reads an image for an actor without media.create only through the reads the asas hands it: with none, a student reads no image, a cover of a course it reads included, and with the courses add-on\'s, only those covers', async () => {
  const tenant = await roleTenant('covers-227f')
  const { headers } = tenant.people.admin
  const [shown, loose] = [await uploadedImage(headers, tenant.options, 'shown.png'), await uploadedImage(headers, tenant.options, 'loose.png')]
  await courses.operations.create({ title: 'Shown 227f', cover: shown }, tenant.options)
  const student = await asas.auth.actor(tenant.people.student.headers)
  const registrar = await asas.auth.actor(tenant.people.registrar.headers)
  const readOf = (reads: Parameters<typeof mediaKayan>[0]['reads']) => mediaKayan({ reads })[0].access!.read! as (args: { user: unknown }) => Promise<unknown>
  assert.equal(await readOf([])({ user: student }), false, 'with no reads handed in, a student reads no image')
  assert.deepEqual(await readOf([coverReads])({ user: student }), { id: { in: [shown] } }, 'with the courses add-on\'s, the cover of the course it reads and nothing else')
  assert.ok(!JSON.stringify(await readOf([coverReads])({ user: student })).includes(loose), 'never an image no course names')
  assert.equal(await readOf([])({ user: registrar }), true, 'a holder of media.create reads every image of its organization either way')
  // A read that would open every image, by a cast `true` or a filter of nothing, refuses rather than opens.
  for (const [answer, what] of [[true, 'true'], [{}, 'an empty filter'], [null, 'null']] as const) {
    const opening = Object.defineProperty(async () => answer as never, 'name', { value: 'openingRead' })
    await assert.rejects(readOf([coverReads, opening])({ user: student }), /openingRead answered .* which would open every image/, `a read answering ${what} is refused`)
  }
})

test('227c. a title, a tag\'s name, a role\'s name and label and the site title are trimmed, so one of spaces alone is refused as required on publish, and a draft keeps it', async () => {
  const tenant = await roleTenant('trim-227c')
  const spaces = '    '
  const refused = async (path: string, input: unknown, field: string) => {
    const answer = await tenant.as('admin', path, input)
    assert.equal(answer.status, 400, `${path}: ${JSON.stringify(answer.body)}`)
    const issues = ((answer.body.data as { params?: { issues?: { path: unknown; message: string }[] } }).params?.issues ?? [])
    assert.ok(issues.some((issue) => String(issue.path).startsWith(field) && issue.message.endsWith('.required')), `${path}: refused as required at ${field}: ${JSON.stringify(issues)}`)
  }
  await refused('courses/create', { title: spaces }, 'title')
  const course = await courses.operations.create({ title: '  Trimmed 227c  ' }, tenant.options)
  assert.equal(course.title, 'Trimmed 227c', 'a title is stored without the spaces around it')
  await refused('courses/update', { id: course.id, title: spaces }, 'title')
  const draft = await tenant.as('admin', 'courses/update?draft=true', { id: course.id, title: spaces })
  assert.equal(draft.status, 200, `a draft save still skips required: ${JSON.stringify(draft.body)}`)
  await refused('tags/create', { name: { en: spaces, ar: 'وسم' } }, 'name')
  await refused('roles/create', { name: spaces, label: { en: 'Role', ar: 'دور' }, permissions: [] }, 'name')
  await refused('roles/create', { name: 'trimmed-227c', label: { en: spaces, ar: 'دور' }, permissions: [] }, 'label')
  await refused('settings/update', { siteTitle: spaces }, 'siteTitle')
})

